export const GLOSTAR_ERWEITERUNG = [
  {id:"sun",icon:"sun",name_de:"Sonne",sum_de:"Der Stern im Zentrum unseres Sonnensystems, der Erde und Planeten Licht und Wärme liefert.",exp_de:"Die Sonne ist ein mittelgroßer Stern, in dessen Kern Wasserstoff zu Helium fusioniert. Ihre Strahlung hält die Erde warm und treibt Wetter und Photosynthese an. In rund fünf Milliarden Jahren wird sie sich zu einem Roten Riesen ausdehnen.",name_en:"Sun",sum_en:"The star at the center of our Solar System that gives Earth and the planets light and warmth.",exp_en:"The Sun is a medium-sized star whose core fuses hydrogen into helium. Its radiation keeps Earth warm and drives weather and photosynthesis. In about five billion years it will expand into a red giant.",name_es:"Sol",sum_es:"La estrella en el centro de nuestro sistema solar que da luz y calor a la Tierra y los planetas.",exp_es:"El Sol es una estrella de tamaño medio cuyo núcleo fusiona hidrógeno en helio. Su radiación mantiene cálida la Tierra e impulsa el clima y la fotosíntesis. Dentro de unos cinco mil millones de años se expandirá hasta convertirse en una gigante roja.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="20" fill="#fff"/><path d="M100 8v14M100 78v14M58 50H44M156 50h-14M70 20l10 10M130 80l-10-10M130 20l-10 10M70 80l10-10" stroke="#fff" stroke-width="3"/></svg>`,related:["star","solar-flare","solar-system"]},
  {id:"moon",icon:"moon",name_de:"Mond",sum_de:"Der einzige natürliche Trabant der Erde, der sie in rund 27 Tagen umkreist.",exp_de:"Der Mond stabilisiert die Erdachse und erzeugt mit seiner Anziehung Ebbe und Flut. Er entstand vermutlich aus Trümmern, die nach dem Einschlag eines großen Körpers in die frühe Erde zurückblieben. Weil er der Erde immer dieselbe Seite zeigt, ist er gebunden rotierend.",name_en:"Moon",sum_en:"Earth's only natural satellite, orbiting it in about 27 days.",exp_en:"The Moon stabilises Earth's axis and, through its gravity, drives the tides. It probably formed from debris left after a large body struck the young Earth. Because it always shows Earth the same face, it is tidally locked.",name_es:"Luna",sum_es:"El único satélite natural de la Tierra, que la orbita en unos 27 días.",exp_es:"La Luna estabiliza el eje terrestre y, con su gravedad, provoca las mareas. Probablemente se formó con los restos que quedaron tras el impacto de un gran cuerpo contra la Tierra joven. Como muestra siempre la misma cara, tiene rotación sincrónica.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="70" cy="50" r="18" fill="#fff"/><circle cx="100" cy="50" r="18" fill="none" stroke="#fff"/><path d="M100 32a18 18 0 0 0 0 36" fill="#fff"/><path d="M100 32a18 18 0 0 1 0 36" fill="#000"/><circle cx="140" cy="50" r="7" fill="#fff" opacity=".8"/></svg>`,related:["moon-phase","earth","tidal-locking"]},
  {id:"earth",icon:"planet",name_de:"Erde",sum_de:"Unser Heimatplanet und der einzige bekannte Ort mit Leben.",exp_de:"Die Erde ist der dritte Planet von der Sonne und besitzt flüssiges Wasser an der Oberfläche, eine Atmosphäre und ein schützendes Magnetfeld. Ihre Neigung von etwa 23,4 Grad verursacht die Jahreszeiten. Sie ist der größte der vier inneren Gesteinsplaneten.",name_en:"Earth",sum_en:"Our home planet and the only known place with life.",exp_en:"Earth is the third planet from the Sun and has liquid water on its surface, an atmosphere and a protective magnetic field. Its axial tilt of about 23.4 degrees causes the seasons. It is the largest of the four inner rocky planets.",name_es:"Tierra",sum_es:"Nuestro planeta natal y el único lugar conocido con vida.",exp_es:"La Tierra es el tercer planeta desde el Sol y tiene agua líquida en su superficie, una atmósfera y un campo magnético protector. Su inclinación axial de unos 23,4 grados provoca las estaciones. Es el mayor de los cuatro planetas rocosos interiores.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="34" fill="none" stroke="#fff" stroke-width="2"/><path d="M66 50h68M100 16c-14 12-14 56 0 68M100 16c14 12 14 56 0 68M72 32c18 6 38 6 56 0M72 68c18-6 38-6 56 0" fill="none" stroke="#fff" stroke-width="1" opacity=".7"/></svg>`,related:["sun","moon","atmosphere"]},
  {id:"mercury",icon:"planet",name_de:"Merkur",sum_de:"Der kleinste Planet und der Sonne am nächsten.",exp_de:"Merkur umkreist die Sonne in nur 88 Tagen. Weil er kaum Atmosphäre hat, schwanken die Temperaturen zwischen etwa 430 Grad am Tag und minus 180 Grad in der Nacht. Er ist nach einem römischen Götterboten benannt.",name_en:"Mercury",sum_en:"The smallest planet and the closest to the Sun.",exp_en:"Mercury orbits the Sun in only 88 days. Because it has almost no atmosphere, temperatures swing from about 430 degrees during the day to minus 180 at night. It is named after the Roman messenger god.",name_es:"Mercurio",sum_es:"El planeta más pequeño y el más cercano al Sol.",exp_es:"Mercurio orbita el Sol en solo 88 días. Al no tener apenas atmósfera, las temperaturas oscilan entre unos 430 grados de día y menos 180 de noche. Debe su nombre al mensajero de los dioses romanos.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="40" cy="50" r="20" fill="#fff"/><circle cx="120" cy="50" r="7" fill="none" stroke="#fff" stroke-width="2"/><path d="M60 50h40" stroke="#fff" stroke-dasharray="3 3" opacity=".6"/><circle cx="150" cy="50" r="3" fill="#fff"/></svg>`,related:["sun","venus","solar-system"]},
  {id:"venus",icon:"planet",name_de:"Venus",sum_de:"Der zweitinnerste Planet, von dichter Wolkendecke umhüllt.",exp_de:"Venus ähnelt der Erde in Größe und Masse, doch ein extremer Treibhauseffekt macht sie zum heißesten Planeten: rund 460 Grad an der Oberfläche. Sie ist der hellste Planet an unserem Himmel und wird daher Morgen- oder Abendstern genannt.",name_en:"Venus",sum_en:"The second planet from the Sun, wrapped in thick clouds.",exp_en:"Venus is similar to Earth in size and mass, but a runaway greenhouse effect makes it the hottest planet, about 460 degrees at the surface. It is the brightest planet in our sky, which is why it is called the morning or evening star.",name_es:"Venus",sum_es:"El segundo planeta desde el Sol, cubierto por densas nubes.",exp_es:"Venus es parecido a la Tierra en tamaño y masa, pero un efecto invernadero descontrolado lo convierte en el planeta más caliente, unos 460 grados en la superficie. Es el planeta más brillante de nuestro cielo, por eso se le llama lucero del alba o de la tarde.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="26" fill="none" stroke="#fff" stroke-width="2"/><path d="M76 40c16 6 32 6 48 0M74 52c18 6 34 6 52 0M76 64c16-6 32-6 48 0" fill="none" stroke="#fff" stroke-width="1.2" opacity=".8"/></svg>`,related:["earth","mercury","atmosphere"]},
  {id:"mars",icon:"planet",name_de:"Mars",sum_de:"Der rote Planet, Ziel zahlreicher Raumsonden und Rover.",exp_de:"Mars verdankt seine rostrote Farbe eisenhaltigem Staub. Er besitzt den höchsten Vulkan des Sonnensystems, Olympus Mons, und ein riesiges Canyonsystem. Spuren von Wasser lassen Forscher nach früherem oder heutigem Leben suchen.",name_en:"Mars",sum_en:"The red planet, target of many probes and rovers.",exp_en:"Mars owes its rusty red colour to iron-rich dust. It has the tallest volcano in the Solar System, Olympus Mons, and a huge canyon system. Traces of water lead researchers to search for past or present life.",name_es:"Marte",sum_es:"El planeta rojo, objetivo de numerosas sondas y róveres.",exp_es:"Marte debe su color rojo herrumbroso al polvo rico en hierro. Tiene el volcán más alto del sistema solar, el monte Olimpo, y un enorme sistema de cañones. Las huellas de agua llevan a buscar vida pasada o presente.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="26" fill="none" stroke="#fff" stroke-width="2"/><path d="M100 24a10 10 0 0 0 0 14M100 76a10 10 0 0 1 0-14" fill="#fff" opacity=".9"/><circle cx="90" cy="46" r="2" fill="#fff"/><circle cx="112" cy="58" r="2.5" fill="#fff"/><circle cx="104" cy="40" r="1.5" fill="#fff"/></svg>`,related:["earth","habitable-zone","atmosphere"]},
  {id:"jupiter",icon:"planet",name_de:"Jupiter",sum_de:"Der größte Planet des Sonnensystems, ein Gasriese mit großem roten Fleck.",exp_de:"Jupiter ist massereicher als alle anderen Planeten zusammen. Der Große Rote Fleck ist ein Sturm, der seit Jahrhunderten tobt. Seine vielen Monde, darunter die vier galileischen, bilden ein eigenes System.",name_en:"Jupiter",sum_en:"The largest planet, a gas giant with the Great Red Spot.",exp_en:"Jupiter is more massive than all the other planets combined. The Great Red Spot is a storm that has raged for centuries. Its many moons, including the four Galilean ones, form a system of their own.",name_es:"Júpiter",sum_es:"El planeta más grande, un gigante gaseoso con la Gran Mancha Roja.",exp_es:"Júpiter tiene más masa que todos los demás planetas juntos. La Gran Mancha Roja es una tormenta que lleva siglos activa. Sus muchas lunas, entre ellas las cuatro galileanas, forman un sistema propio.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="28" fill="none" stroke="#fff" stroke-width="2"/><path d="M74 40h52M72 50h56M74 60h52" stroke="#fff" stroke-width="1" opacity=".6"/><ellipse cx="100" cy="46" rx="7" ry="4.5" fill="#fff" opacity=".85"/><circle cx="160" cy="50" r="4" fill="#fff"/><circle cx="168" cy="38" r="2.5" fill="#fff"/></svg>`,related:["saturn","gas-giant","sun"]},
  {id:"saturn",icon:"planet",name_de:"Saturn",sum_de:"Der Gasriese mit dem auffälligsten Ringsystem.",exp_de:"Saturns Ringe bestehen aus unzähligen Eis- und Gesteinsbrocken. Sie sind sehr breit, aber nur wenige Meter bis Kilometer dick. Der Mond Titan besitzt eine dichte Atmosphäre und Seen aus flüssigem Methan.",name_en:"Saturn",sum_en:"The gas giant with the most striking ring system.",exp_en:"Saturn's rings are made of countless chunks of ice and rock. They are very wide but only metres to kilometres thick. Its moon Titan has a dense atmosphere and lakes of liquid methane.",name_es:"Saturno",sum_es:"El gigante gaseoso con el sistema de anillos más llamativo.",exp_es:"Los anillos de Saturno están formados por innumerables fragmentos de hielo y roca. Son muy anchos pero solo tienen de metros a kilómetros de grosor. Su luna Titán posee una atmósfera densa y lagos de metano líquido.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="18" fill="#fff"/><ellipse cx="100" cy="50" rx="52" ry="12" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M48 50a52 12 0 0 0 104 0" fill="none" stroke="#fff" stroke-width="1.5"/><ellipse cx="100" cy="50" rx="40" ry="9" fill="none" stroke="#fff" stroke-width=".8" opacity=".6"/></svg>`,related:["jupiter","ring-system","gas-giant"]},
  {id:"uranus",icon:"planet",name_de:"Uranus",sum_de:"Ein Eisriese, der auf der Seite liegend um die Sonne rollt.",exp_de:"Uranus ist um etwa 98 Grad geneigt, sodass er praktisch auf der Seite kreist. Dadurch dauert jede seiner Jahreszeiten rund 21 Jahre. Sein blaugrünes Aussehen stammt vom Methan in der Atmosphäre.",name_en:"Uranus",sum_en:"An ice giant that rolls around the Sun on its side.",exp_en:"Uranus is tilted by about 98 degrees, so it orbits practically on its side. As a result each of its seasons lasts about 21 years. Its blue-green colour comes from methane in the atmosphere.",name_es:"Urano",sum_es:"Un gigante helado que gira alrededor del Sol recostado de lado.",exp_es:"Urano está inclinado unos 98 grados, por lo que orbita prácticamente de lado. Por eso cada estación dura unos 21 años. Su color azul verdoso se debe al metano de su atmósfera.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="16" fill="none" stroke="#fff" stroke-width="2"/><ellipse cx="100" cy="50" rx="10" ry="30" fill="none" stroke="#fff" stroke-width="1"/><path d="M100 50V18" stroke="#fff" stroke-width=".8" stroke-dasharray="3 3" opacity=".6"/><circle cx="140" cy="40" r="2" fill="#fff"/></svg>`,related:["neptune","ice-giant","ring-system"]},
  {id:"neptune",icon:"planet",name_de:"Neptun",sum_de:"Der äußerste Planet, ein kalter Eisriese mit den schnellsten Stürmen.",exp_de:"Neptun wurde 1846 anhand von Berechnungen entdeckt, noch bevor man ihn sah. In seiner Atmosphäre toben Winde mit über 2000 Kilometern pro Stunde. Ein Umlauf um die Sonne dauert fast 165 Jahre.",name_en:"Neptune",sum_en:"The outermost planet, a cold ice giant with the fastest winds.",exp_en:"Neptune was discovered in 1846 through calculations before it was seen. Winds in its atmosphere reach over 2000 kilometres per hour. One orbit around the Sun takes almost 165 years.",name_es:"Neptuno",sum_es:"El planeta más exterior, un gélido gigante helado con los vientos más rápidos.",exp_es:"Neptuno se descubrió en 1846 mediante cálculos antes de verlo. En su atmósfera soplan vientos de más de 2000 kilómetros por hora. Una vuelta alrededor del Sol dura casi 165 años.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="22" fill="none" stroke="#fff" stroke-width="2"/><path d="M80 44c12-4 26-4 40 0M78 56c14 4 30 4 44 0" fill="none" stroke="#fff" stroke-width="1" opacity=".7"/><path d="M40 30c10 6 8 14 0 20M40 50c10 6 8 14 0 20" fill="none" stroke="#fff" opacity=".5"/><circle cx="150" cy="66" r="4" fill="none" stroke="#fff"/></svg>`,related:["uranus","ice-giant","pluto"]},
  {id:"pluto",icon:"planet",name_de:"Pluto",sum_de:"Ein Zwergplanet im Kuipergürtel, früher als neunter Planet gezählt.",exp_de:"Pluto umkreist die Sonne in stark elliptischer Bahn und braucht dafür 248 Jahre. 2006 wurde er zum Zwergplaneten herabgestuft. Die Sonde New Horizons fotografierte 2015 erstmals seine Oberfläche.",name_en:"Pluto",sum_en:"A dwarf planet in the Kuiper Belt, once counted as the ninth planet.",exp_en:"Pluto orbits the Sun on a highly elliptical path and needs 248 years to do so. In 2006 it was reclassified as a dwarf planet. The New Horizons probe photographed its surface for the first time in 2015.",name_es:"Plutón",sum_es:"Un planeta enano del cinturón de Kuiper, antes contado como noveno planeta.",exp_es:"Plutón orbita el Sol en una trayectoria muy elíptica y tarda 248 años. En 2006 fue reclasificado como planeta enano. La sonda New Horizons fotografió su superficie por primera vez en 2015.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="90" cy="52" r="12" fill="none" stroke="#fff" stroke-width="2"/><circle cx="124" cy="42" r="6" fill="none" stroke="#fff" stroke-width="1.5"/><ellipse cx="105" cy="48" rx="34" ry="16" fill="none" stroke="#fff" stroke-width="1" stroke-dasharray="3 4" opacity=".5"/></svg>`,related:["zwergplanet","kuiper-belt","voyager"]},
  {id:"ceres",icon:"asteroid",name_de:"Ceres",sum_de:"Der größte Körper im Asteroidengürtel und ein Zwergplanet.",exp_de:"Ceres macht etwa ein Drittel der Masse des gesamten Asteroidengürtels aus. Unter ihrer Kruste könnten sich Wassereis und Salzlösungen befinden. Die Sonde Dawn umkreiste sie ab 2015.",name_en:"Ceres",sum_en:"The largest body in the asteroid belt and a dwarf planet.",exp_en:"Ceres holds about a third of the mass of the entire asteroid belt. Beneath its crust there may be water ice and salty brines. The Dawn probe orbited it from 2015.",name_es:"Ceres",sum_es:"El mayor cuerpo del cinturón de asteroides y un planeta enano.",exp_es:"Ceres concentra cerca de un tercio de la masa de todo el cinturón de asteroides. Bajo su corteza podría haber hielo de agua y salmueras. La sonda Dawn la orbitó desde 2015.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="24" fill="none" stroke="#fff" stroke-width="2"/><circle cx="92" cy="44" r="4" fill="none" stroke="#fff"/><circle cx="110" cy="58" r="3" fill="none" stroke="#fff"/><circle cx="106" cy="40" r="2.5" fill="#fff"/><circle cx="88" cy="60" r="2" fill="#fff"/></svg>`,related:["asteroid-belt","zwergplanet","pluto"]},
  {id:"solar-system",icon:"orbit",name_de:"Sonnensystem",sum_de:"Die Sonne und alle Körper, die sie umkreisen.",exp_de:"Zum Sonnensystem gehören acht Planeten, ihre Monde, Zwergplaneten, Asteroiden und Kometen sowie Staub und Gas. Fast die gesamte Masse steckt in der Sonne. Der äußerste Bereich ist die Oortsche Wolke.",name_en:"Solar System",sum_en:"The Sun and all the bodies that orbit it.",exp_en:"The Solar System includes eight planets, their moons, dwarf planets, asteroids and comets, plus dust and gas. Almost all of its mass is in the Sun. Its outermost region is the Oort Cloud.",name_es:"Sistema Solar",sum_es:"El Sol y todos los cuerpos que lo orbitan.",exp_es:"El sistema solar incluye ocho planetas, sus lunas, planetas enanos, asteroides y cometas, además de polvo y gas. Casi toda la masa está en el Sol. Su región más exterior es la nube de Oort.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="8" fill="#fff"/><ellipse cx="100" cy="50" rx="30" ry="12" fill="none" stroke="#fff" stroke-width="1"/><ellipse cx="100" cy="50" rx="52" ry="22" fill="none" stroke="#fff" stroke-width="1"/><ellipse cx="100" cy="50" rx="74" ry="32" fill="none" stroke="#fff" stroke-width="1"/><circle cx="130" cy="50" r="2.5" fill="#fff"/><circle cx="60" cy="32" r="2" fill="#fff"/><circle cx="160" cy="66" r="1.8" fill="#fff"/></svg>`,related:["sun","orbit","kuiper-belt"]},
  {id:"kuiper-belt",icon:"orbit",name_de:"Kuipergürtel",sum_de:"Ein ringförmiger Bereich aus eisigen Kleinkörpern jenseits des Neptun.",exp_de:"Der Kuipergürtel erstreckt sich etwa von 30 bis 50 Astronomischen Einheiten von der Sonne. In ihm kreisen viele Zwergplaneten, darunter Pluto. Kurzperiodische Kometen stammen vermutlich aus dieser Region.",name_en:"Kuiper Belt",sum_en:"A ring of icy small bodies beyond Neptune.",exp_en:"The Kuiper Belt stretches from roughly 30 to 50 astronomical units from the Sun. Many dwarf planets orbit within it, including Pluto. Short-period comets probably come from this region.",name_es:"Cinturón de Kuiper",sum_es:"Un anillo de cuerpos helados más allá de Neptuno.",exp_es:"El cinturón de Kuiper se extiende aproximadamente de 30 a 50 unidades astronómicas del Sol. En él orbitan muchos planetas enanos, incluido Plutón. Los cometas de período corto probablemente provienen de esta región.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="6" fill="#fff"/><ellipse cx="100" cy="50" rx="70" ry="30" fill="none" stroke="#fff" stroke-width="1" stroke-dasharray="3 4"/><circle cx="30" cy="50" r="2" fill="#fff"/><circle cx="170" cy="50" r="2" fill="#fff"/><circle cx="100" cy="20" r="2" fill="#fff"/><circle cx="100" cy="80" r="2" fill="#fff"/><circle cx="55" cy="28" r="1.6" fill="#fff"/><circle cx="145" cy="72" r="1.6" fill="#fff"/></svg>`,related:["zwergplanet","pluto","oort-cloud","orbit"]},
  {id:"asteroid-belt",icon:"asteroid",name_de:"Asteroidengürtel",sum_de:"Die Zone zwischen Mars und Jupiter, in der viele Asteroiden kreisen.",exp_de:"Im Asteroidengürtel sammeln sich Millionen kleiner Körper. Sie konnten sich nicht zu einem Planeten zusammenschließen, weil Jupiters Schwerkraft sie störte. Der größte Körper ist der Zwergplanet Ceres.",name_en:"Asteroid Belt",sum_en:"The zone between Mars and Jupiter where many asteroids orbit.",exp_en:"Millions of small bodies gather in the asteroid belt. They never combined into a planet because Jupiter's gravity disturbed them. The largest body is the dwarf planet Ceres.",name_es:"Cinturón de Asteroides",sum_es:"La zona entre Marte y Júpiter donde orbitan muchos asteroides.",exp_es:"En el cinturón de asteroides se reúnen millones de cuerpos pequeños. Nunca llegaron a formar un planeta porque la gravedad de Júpiter los alteró. El mayor es el planeta enano Ceres.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="6" fill="#fff"/><ellipse cx="100" cy="50" rx="60" ry="26" fill="none" stroke="#fff" stroke-width="1"/><circle cx="40" cy="50" r="2.5" fill="#fff"/><circle cx="48" cy="40" r="2" fill="#fff"/><circle cx="160" cy="50" r="2.5" fill="#fff"/><circle cx="152" cy="60" r="2" fill="#fff"/><circle cx="100" cy="24" r="2" fill="#fff"/><circle cx="100" cy="76" r="2" fill="#fff"/></svg>`,related:["ceres","mars","jupiter","asteroid"]},
  {id:"oort-cloud",icon:"comet",name_de:"Oortsche Wolke",sum_de:"Eine riesige, kugelförmige Hülle eisiger Körper am Rand des Sonnensystems.",exp_de:"Die Oortsche Wolke liegt vermutlich zwischen 2000 und 100.000 Astronomischen Einheiten von der Sonne. Aus ihr stammen die langperiodischen Kometen. Direkt beobachtet wurde sie noch nie.",name_en:"Oort Cloud",sum_en:"A vast spherical shell of icy bodies at the edge of the Solar System.",exp_en:"The Oort Cloud is thought to lie between 2000 and 100,000 astronomical units from the Sun. Long-period comets come from it. It has never been observed directly.",name_es:"Nube de Oort",sum_es:"Una enorme envoltura esférica de cuerpos helados en el borde del sistema solar.",exp_es:"Se cree que la nube de Oort se extiende entre 2000 y 100.000 unidades astronómicas del Sol. De ella provienen los cometas de período largo. Nunca se ha observado directamente.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="5" fill="#fff"/><ellipse cx="100" cy="50" rx="86" ry="40" fill="none" stroke="#fff" stroke-width="1" stroke-dasharray="2 5" opacity=".6"/><circle cx="24" cy="30" r="1.8" fill="#fff"/><circle cx="176" cy="72" r="1.8" fill="#fff"/><circle cx="100" cy="12" r="1.8" fill="#fff"/><circle cx="60" cy="82" r="1.8" fill="#fff"/></svg>`,related:["comet","kuiper-belt","solar-system"]},
  {id:"terrestrial-planet",icon:"planet",name_de:"Gesteinsplanet",sum_de:"Ein Planet aus Gestein und Metall mit fester Oberfläche.",exp_de:"Die vier inneren Planeten Merkur, Venus, Erde und Mars sind Gesteinsplaneten. Sie haben eine feste Kruste und einen Metallkern. Ihre dichten Atmosphären, falls vorhanden, unterscheiden sich stark.",name_en:"Rocky Planet",sum_en:"A planet made of rock and metal with a solid surface.",exp_en:"The four inner planets Mercury, Venus, Earth and Mars are rocky planets. They have a solid crust and a metal core. Their dense atmospheres, where present, differ greatly.",name_es:"Planeta Rocoso",sum_es:"Un planeta de roca y metal con superficie sólida.",exp_es:"Los cuatro planetas interiores Mercurio, Venus, Tierra y Marte son planetas rocosos. Tienen una corteza sólida y un núcleo metálico. Sus densas atmósferas, cuando existen, son muy distintas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="30" fill="none" stroke="#fff" stroke-width="2"/><circle cx="100" cy="50" r="20" fill="none" stroke="#fff" stroke-width="1" opacity=".7"/><circle cx="100" cy="50" r="9" fill="#fff"/></svg>`,related:["earth","mercury","mars","gas-giant"]},
  {id:"gas-giant",icon:"planet",name_de:"Gasriese",sum_de:"Ein sehr großer Planet, der überwiegend aus Wasserstoff und Helium besteht.",exp_de:"Jupiter und Saturn sind Gasriesen. Sie haben keinen festen Boden, sondern gehen von einer dichten Atmosphäre in tiefere, heißere Schichten über. Ihre schnelle Rotation und Stürme prägen das Streifenmuster.",name_en:"Gas Giant",sum_en:"A very large planet made mainly of hydrogen and helium.",exp_en:"Jupiter and Saturn are gas giants. They have no solid ground but pass from a dense atmosphere into deeper, hotter layers. Their fast rotation and storms shape their banded appearance.",name_es:"Gigante Gaseoso",sum_es:"Un planeta muy grande formado sobre todo por hidrógeno y helio.",exp_es:"Júpiter y Saturno son gigantes gaseosos. No tienen suelo sólido, sino que pasan de una atmósfera densa a capas más profundas y calientes. Su rápida rotación y sus tormentas forman las bandas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="30" fill="none" stroke="#fff" stroke-width="2"/><path d="M72 38h56M70 50h60M72 62h56" stroke="#fff" stroke-width="1.2" opacity=".7"/></svg>`,related:["jupiter","saturn","ice-giant","atmosphere"]},
  {id:"ice-giant",icon:"planet",name_de:"Eisriese",sum_de:"Ein Planet aus Wasser, Ammoniak und Methan über einem kleinen Kern.",exp_de:"Uranus und Neptun zählen zu den Eisriesen. Ihre inneren Schichten bestehen aus heißem, dichtem Eis und Gasen. Das Methan in ihrer Atmosphäre gibt ihnen die bläuliche Farbe.",name_en:"Ice Giant",sum_en:"A planet of water, ammonia and methane around a small core.",exp_en:"Uranus and Neptune are ice giants. Their inner layers consist of hot, dense ices and gases. Methane in their atmospheres gives them their bluish colour.",name_es:"Gigante Helado",sum_es:"Un planeta de agua, amoníaco y metano alrededor de un núcleo pequeño.",exp_es:"Urano y Neptuno son gigantes helados. Sus capas internas están formadas por hielos y gases calientes y densos. El metano de su atmósfera les da el color azulado.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="24" fill="none" stroke="#fff" stroke-width="2"/><path d="M78 44h44M76 54h48" stroke="#fff" stroke-width="1" opacity=".6"/><circle cx="100" cy="50" r="34" fill="none" stroke="#fff" stroke-width=".8" stroke-dasharray="2 4" opacity=".4"/></svg>`,related:["uranus","neptune","gas-giant"]},
  {id:"ring-system",icon:"planet",name_de:"Ringsystem",sum_de:"Flache Scheiben aus Staub und Eisbrocken um einen Planeten.",exp_de:"Alle vier Riesenplaneten besitzen Ringsysteme, am auffälligsten Saturn. Die Ringe bestehen aus unzähligen Teilchen, die den Planeten auf Kreisbahnen umlaufen. Sie können durch zerbrochene Monde oder eingefangenes Material entstanden sein.",name_en:"Planetary Rings",sum_en:"Flat disks of dust and ice chunks around a planet.",exp_en:"All four giant planets have ring systems, the most striking around Saturn. The rings are made of countless particles orbiting the planet. They may have formed from shattered moons or captured material.",name_es:"Anillos Planetarios",sum_es:"Discos planos de polvo y fragmentos de hielo alrededor de un planeta.",exp_es:"Los cuatro gigantes tienen sistemas de anillos, el más llamativo en Saturno. Los anillos están formados por incontables partículas que orbitan el planeta. Pueden haberse formado a partir de lunas destruidas o material capturado.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="16" fill="#fff"/><ellipse cx="100" cy="50" rx="56" ry="14" fill="none" stroke="#fff" stroke-width="1.4"/><ellipse cx="100" cy="50" rx="44" ry="10" fill="none" stroke="#fff" stroke-width=".8" opacity=".6"/></svg>`,related:["saturn","jupiter","uranus","neptune"]},
  {id:"protoplanetary-disk",icon:"orbit",name_de:"Protoplanetare Scheibe",sum_de:"Eine rotierende Scheibe aus Gas und Staub, aus der Planeten entstehen.",exp_de:"Um einen jungen Stern bildet sich aus der übrig gebliebenen Materie eine Scheibe. In ihr verklumpen Staubteilchen zu immer größeren Körpern und schließlich zu Planeten. Solche Scheiben sind zum Beispiel im Orionnebel zu sehen.",name_en:"Protoplanetary Disk",sum_en:"A rotating disk of gas and dust where planets form.",exp_en:"Around a young star, leftover material settles into a disk. Within it, dust grains clump into ever larger bodies and finally into planets. Such disks can be seen, for example, in the Orion Nebula.",name_es:"Disco Protoplanetario",sum_es:"Un disco giratorio de gas y polvo donde nacen los planetas.",exp_es:"Alrededor de una estrella joven, el material sobrante forma un disco. En él, los granos de polvo se agrupan en cuerpos cada vez mayores y finalmente en planetas. Estos discos se observan, por ejemplo, en la nebulosa de Orión.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="7" fill="#fff"/><ellipse cx="100" cy="50" rx="76" ry="20" fill="none" stroke="#fff" stroke-width="1.2" opacity=".7"/><ellipse cx="100" cy="50" rx="52" ry="13" fill="none" stroke="#fff" stroke-width="1" opacity=".5"/><circle cx="152" cy="42" r="2" fill="#fff"/><circle cx="54" cy="58" r="2" fill="#fff"/></svg>`,related:["star-formation","accretion-disk","solar-system"]},
  {id:"atmosphere",icon:"planet",name_de:"Atmosphäre",sum_de:"Die Gashülle eines Himmelskörpers, die seine Oberfläche umgibt.",exp_de:"Eine Atmosphäre entsteht aus Gasen, die ein Körper durch Schwerkraft festhält. Sie kann Wärme speichern, Strahlung filtern und Wetter erzeugen. Merkur hat fast keine, Venus eine extrem dichte, die Erde eine schützende.",name_en:"Atmosphere",sum_en:"The layer of gas surrounding a celestial body.",exp_en:"An atmosphere forms from gases that a body holds by gravity. It can trap heat, filter radiation and create weather. Mercury has almost none, Venus an extremely dense one, Earth a protective one.",name_es:"Atmósfera",sum_es:"La capa de gas que rodea a un cuerpo celeste.",exp_es:"Una atmósfera se forma con los gases que un cuerpo retiene por gravedad. Puede atrapar calor, filtrar radiación y generar clima. Mercurio casi no tiene, Venus una muy densa y la Tierra una protectora.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="56" r="16" fill="#fff"/><ellipse cx="100" cy="40" rx="34" ry="10" fill="none" stroke="#fff" opacity=".6"/><ellipse cx="100" cy="30" rx="42" ry="12" fill="none" stroke="#fff" opacity=".4"/><ellipse cx="100" cy="20" rx="50" ry="14" fill="none" stroke="#fff" opacity=".25"/></svg>`,related:["venus","earth","aurora"]},
  {id:"binary-star",icon:"star",name_de:"Doppelstern",sum_de:"Zwei Sterne, die einander umkreisen und gemeinsam ein System bilden.",exp_de:"Etwa die Hälfte aller Sterne gehört zu einem System aus zwei oder mehr Sternen. Manche sind so nah, dass sie sich berühren und Materie austauschen. Ihre Bahnen verraten Astronomen die Massen der Sterne.",name_en:"Binary Star",sum_en:"Two stars that orbit each other and form a system.",exp_en:"About half of all stars belong to a system of two or more stars. Some are so close that they touch and exchange matter. Their orbits let astronomers measure stellar masses.",name_es:"Estrella Binaria",sum_es:"Dos estrellas que se orbitan mutuamente y forman un sistema.",exp_es:"Cerca de la mitad de las estrellas pertenecen a un sistema de dos o más estrellas. Algunas están tan cerca que se tocan e intercambian materia. Sus órbitas permiten a los astrónomos medir la masa de las estrellas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="80" cy="50" r="11" fill="#fff"/><circle cx="128" cy="50" r="7" fill="none" stroke="#fff" stroke-width="2"/><ellipse cx="104" cy="50" rx="34" ry="14" fill="none" stroke="#fff" stroke-width=".8" stroke-dasharray="3 4" opacity=".6"/></svg>`,related:["star","cepheid","variable-star"]},
  {id:"variable-star",icon:"star",name_de:"Veränderlicher Stern",sum_de:"Ein Stern, dessen Helligkeit sich mit der Zeit ändert.",exp_de:"Manche Sterne pulsieren, andere werden zeitweise von einem Begleiter bedeckt. Aus dem Rhythmus der Helligkeitsschwankungen lassen sich Größe und Aufbau des Sterns ableiten. Cepheiden dienen als Entfernungsmaßstab.",name_en:"Variable Star",sum_en:"A star whose brightness changes over time.",exp_en:"Some stars pulsate, while others are periodically eclipsed by a companion. The rhythm of the brightness changes reveals a star's size and structure. Cepheids serve as a distance measure.",name_es:"Estrella Variable",sum_es:"Una estrella cuya luminosidad cambia con el tiempo.",exp_es:"Algunas estrellas pulsan y otras son eclipsadas periódicamente por una compañera. El ritmo de los cambios de brillo revela el tamaño y la estructura de la estrella. Las cefeidas sirven como regla de distancia.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="60" cy="50" r="10" fill="#fff"/><path d="M90 62c8-26 16-26 24 0s16 26 24 0 16-26 24 0" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M90 50h84" stroke="#fff" stroke-dasharray="2 4" opacity=".4"/></svg>`,related:["cepheid","binary-star","star"]},
  {id:"cepheid",icon:"star",name_de:"Cepheide",sum_de:"Ein pulsierender Riesenstern, dessen Periode seine Helligkeit verrät.",exp_de:"Bei Cepheiden hängt die Leuchtkraft fest mit der Pulsationsdauer zusammen. Misst man die Periode, kennt man die wahre Helligkeit und kann daraus die Entfernung bestimmen. Henrietta Leavitt entdeckte diesen Zusammenhang 1912.",name_en:"Cepheid",sum_en:"A pulsating giant star whose period reveals its brightness.",exp_en:"In Cepheids the luminosity is tightly linked to the pulsation period. Measuring the period gives the true brightness and thus the distance. Henrietta Leavitt discovered this relation in 1912.",name_es:"Cefeida",sum_es:"Una estrella gigante pulsante cuyo período revela su brillo.",exp_es:"En las cefeidas, la luminosidad está ligada estrechamente al período de pulsación. Medir el período da el brillo real y, con él, la distancia. Henrietta Leavitt descubrió esta relación en 1912.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="46" cy="50" r="12" fill="#fff"/><path d="M74 64c6-22 10-30 16-16s10 14 16-4 10-24 16-8 10 10 16-6 10-18 16-2" fill="none" stroke="#fff" stroke-width="1.4"/></svg>`,related:["variable-star","standard-candle","star"]},
  {id:"red-giant",icon:"star",name_de:"Roter Riese",sum_de:"Ein alter, aufgeblähter Stern am Ende seiner Brennphase.",exp_de:"Wenn ein Stern seinen Wasserstoff im Kern verbraucht hat, dehnt sich seine Hülle stark aus und kühlt ab, während der Kern schrumpft und heißer wird. Unsere Sonne wird in ferner Zukunft zu einem Roten Riesen.",name_en:"Red Giant",sum_en:"An old, bloated star at the end of its burning phase.",exp_en:"When a star has used up the hydrogen in its core, its outer layers expand greatly and cool, while the core shrinks and grows hotter. Our Sun will become a red giant in the distant future.",name_es:"Gigante Roja",sum_es:"Una estrella vieja e hinchada al final de su fase de combustión.",exp_es:"Cuando una estrella agota el hidrógeno de su núcleo, sus capas externas se expanden mucho y se enfrían, mientras el núcleo se contrae y se calienta. Nuestro Sol se convertirá en una gigante roja en un futuro lejano.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="34" fill="none" stroke="#fff" stroke-width="1.5" opacity=".7"/><circle cx="100" cy="50" r="8" fill="#fff"/><circle cx="100" cy="50" r="20" fill="none" stroke="#fff" stroke-width=".8" opacity=".4"/></svg>`,related:["white-dwarf","stellar-evolution","sun"]},
  {id:"white-dwarf",icon:"star",name_de:"Weißer Zwerg",sum_de:"Der heiße, dichte Überrest eines ausgeglühten Sterns.",exp_de:"Ein Weißer Zwerg ist etwa so groß wie die Erde, enthält aber die Masse der Sonne. Er leuchtet nur noch von seiner Restwärme und kühlt über Milliarden Jahre aus. Die Chandrasekhar-Grenze von rund 1,4 Sonnenmassen begrenzt seine Masse.",name_en:"White Dwarf",sum_en:"The hot, dense remnant of a spent star.",exp_en:"A white dwarf is about the size of Earth but holds the mass of the Sun. It shines only from leftover heat and cools over billions of years. The Chandrasekhar limit of about 1.4 solar masses caps its mass.",name_es:"Enana Blanca",sum_es:"El remanente caliente y denso de una estrella agotada.",exp_es:"Una enana blanca es del tamaño de la Tierra pero contiene la masa del Sol. Brilla solo por su calor residual y se enfría durante miles de millones de años. El límite de Chandrasekhar, de unas 1,4 masas solares, limita su masa.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="40" fill="none" stroke="#fff" stroke-width=".8" stroke-dasharray="2 4" opacity=".35"/><circle cx="100" cy="50" r="5" fill="#fff"/><path d="M100 40v-8M100 60v8M90 50h-8M110 50h8" stroke="#fff" stroke-width="1.5"/></svg>`,related:["red-giant","stellar-evolution","neutron-star"]},
  {id:"brown-dwarf",icon:"star",name_de:"Brauner Zwerg",sum_de:"Ein Himmelskörper zwischen Planet und Stern, in dem die Fusion nicht zündet.",exp_de:"Braune Zwerge sind zu massearm, um dauerhaft Wasserstoff zu fusionieren. Sie leuchten schwach im Infraroten und kühlen langsam aus. Manche umkreisen Sterne, viele treiben frei durch die Galaxie.",name_en:"Brown Dwarf",sum_en:"A body between planet and star where fusion never ignites.",exp_en:"Brown dwarfs are too low in mass to fuse hydrogen steadily. They glow faintly in the infrared and cool slowly. Some orbit stars, many drift freely through the galaxy.",name_es:"Enana Marrón",sum_es:"Un cuerpo entre planeta y estrella en el que la fusión no se enciende.",exp_es:"Las enanas marrones tienen muy poca masa para fusionar hidrógeno de forma estable. Brillan débilmente en el infrarrojo y se enfrían lentamente. Algunas orbitan estrellas y muchas vagan libres por la galaxia.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="20" fill="none" stroke="#fff" stroke-width="2" opacity=".7"/><circle cx="100" cy="50" r="20" fill="none" stroke="#fff" stroke-width=".8" stroke-dasharray="3 4" opacity=".4"/><path d="M100 22v-6M100 78v6" stroke="#fff" opacity=".4"/></svg>`,related:["star","gas-giant","nuclear-fusion"]},
  {id:"stellar-evolution",icon:"star",name_de:"Sternentwicklung",sum_de:"Der Lebensweg eines Sterns von der Geburt bis zum Überrest.",exp_de:"Ein Stern entsteht aus einer Gaswolke, verbrennt jahrelang Wasserstoff und bläht sich später zum Riesen auf. Wie er endet, hängt von seiner Masse ab: als Weißer Zwerg, Neutronenstern oder Schwarzes Loch.",name_en:"Stellar Evolution",sum_en:"A star's life path from birth to remnant.",exp_en:"A star is born from a gas cloud, burns hydrogen for millions or billions of years and later swells into a giant. How it ends depends on its mass: as a white dwarf, neutron star or black hole.",name_es:"Evolución Estelar",sum_es:"El camino vital de una estrella, del nacimiento al remanente.",exp_es:"Una estrella nace de una nube de gas, quema hidrógeno durante millones o miles de millones de años y luego se hincha hasta gigante. Su final depende de su masa: enana blanca, estrella de neutrones o agujero negro.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="30" cy="50" r="9" fill="none" stroke="#fff"/><circle cx="78" cy="50" r="14" fill="#fff"/><circle cx="130" cy="50" r="20" fill="none" stroke="#fff" stroke-width="1.5"/><circle cx="172" cy="50" r="5" fill="#fff"/><path d="M41 50h24M94 50h13M152 50h13" stroke="#fff" stroke-dasharray="3 3"/></svg>`,related:["star-formation","red-giant","white-dwarf","neutron-star","blackhole"]},
  {id:"star-formation",icon:"nebula",name_de:"Sternentstehung",sum_de:"Der Prozess, in dem aus kaltem Gas und Staub neue Sterne entstehen.",exp_de:"In dichten, kalten Molekülwolken zieht die Schwerkraft Gas zusammen, bis im Kern eines Protosterns die Fusion zündet. Sternentstehung findet oft in Gruppen statt, etwa im Orionnebel. Junge Sterne können die restliche Wolke mit Strahlung und Winden wegblasen.",name_en:"Star Formation",sum_en:"The process by which new stars form from cold gas and dust.",exp_en:"In dense, cold molecular clouds gravity pulls gas together until fusion ignites in the core of a protostar. Star formation often happens in groups, for example in the Orion Nebula. Young stars can blow the remaining cloud away with radiation and winds.",name_es:"Formación Estelar",sum_es:"El proceso por el que nacen nuevas estrellas a partir de gas y polvo fríos.",exp_es:"En densas nubes moleculares frías, la gravedad concentra el gas hasta que la fusión se enciende en el núcleo de una protoestrella. La formación estelar suele ocurrir en grupos, por ejemplo en la nebulosa de Orión. Las estrellas jóvenes pueden dispersar el resto de la nube con radiación y vientos.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><ellipse cx="100" cy="50" rx="60" ry="26" fill="none" stroke="#fff" opacity=".5"/><circle cx="100" cy="50" r="5" fill="#fff"/><path d="M70 30l14 12M130 30l-14 12M70 70l14-12M130 70l-14-12" stroke="#fff" stroke-width="1" opacity=".5"/></svg>`,related:["molecular-cloud","nebula","stellar-evolution"]},
  {id:"nuclear-fusion",icon:"supernova",name_de:"Kernfusion",sum_de:"Die Verschmelzung leichter Atomkerne, die Sterne zum Leuchten bringt.",exp_de:"In Sternen verschmelzen Wasserstoffkerne zu Helium, wobei Energie frei wird. Schwerere Elemente bis zum Eisen entstehen in späteren Fusionsstufen. Ohne Kernfusion gäbe es das Licht der Sterne nicht.",name_en:"Nuclear Fusion",sum_en:"The merging of light atomic nuclei that makes stars shine.",exp_en:"In stars, hydrogen nuclei fuse into helium and release energy. Heavier elements up to iron form in later fusion stages. Without nuclear fusion there would be no starlight.",name_es:"Fusión Nuclear",sum_es:"La fusión de núcleos atómicos ligeros que hace brillar a las estrellas.",exp_es:"En las estrellas, los núcleos de hidrógeno se fusionan en helio liberando energía. Los elementos más pesados hasta el hierro se forman en etapas posteriores. Sin la fusión nuclear no existiría la luz de las estrellas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="80" cy="50" r="14" fill="none" stroke="#fff" stroke-width="2"/><circle cx="120" cy="50" r="14" fill="none" stroke="#fff" stroke-width="2"/><path d="M96 50h8" stroke="#fff" stroke-width="2"/><circle cx="100" cy="30" r="2" fill="#fff"/><circle cx="100" cy="70" r="2" fill="#fff"/></svg>`,related:["sun","star","supernova"]},
  {id:"magnetar",icon:"pulsar",name_de:"Magnetar",sum_de:"Ein Neutronenstern mit einem extrem starken Magnetfeld.",exp_de:"Magnetare gehören zu den stärksten Magneten im Universum. Ihre Felder können Materie in der Nähe verzerren und Röntgenblitze aussenden. Sie entstehen vermutlich nach besonders energiereichen Supernovae.",name_en:"Magnetar",sum_en:"A neutron star with an extremely strong magnetic field.",exp_en:"Magnetars are among the strongest magnets in the universe. Their fields can distort nearby matter and emit X-ray bursts. They are thought to form after especially energetic supernovae.",name_es:"Magnetar",sum_es:"Una estrella de neutrones con un campo magnético extremadamente fuerte.",exp_es:"Los magnetares están entre los imanes más potentes del universo. Sus campos pueden deformar la materia cercana y emitir destellos de rayos X. Se cree que se forman tras supernovas especialmente energéticas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="8" fill="#fff"/><path d="M100 42c-30-20-50 0-50 8s20 28 50 8M100 42c30-20 50 0 50 8s-20 28-50 8" fill="none" stroke="#fff" stroke-width="1.2" opacity=".7"/></svg>`,related:["neutron-star","pulsar","supernova"]},
  {id:"gamma-ray-burst",icon:"supernova",name_de:"Gammablitz",sum_de:"Ein kurzer, extrem energiereicher Ausbruch von Gammastrahlung aus dem All.",exp_de:"Gammablitze gehören zu den hellsten Ereignissen im Universum. Längere Blitze stammen wohl vom Kollaps massereicher Sterne, kurze von der Verschmelzung kompakter Objekte. Sie leuchten nur Sekunden bis Minuten.",name_en:"Gamma-Ray Burst",sum_en:"A brief, extremely energetic burst of gamma rays from space.",exp_en:"Gamma-ray bursts are among the brightest events in the universe. Longer bursts probably come from the collapse of massive stars, shorter ones from merging compact objects. They shine for only seconds to minutes.",name_es:"Estallido de Rayos Gamma",sum_es:"Una breve y extremadamente energética emisión de rayos gamma del espacio.",exp_es:"Los estallidos de rayos gamma están entre los eventos más brillantes del universo. Los más largos probablemente provienen del colapso de estrellas masivas y los cortos de la fusión de objetos compactos. Brillan solo de segundos a minutos.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="6" fill="#fff"/><path d="M100 50L20 20M100 50L180 20M100 50L20 80M100 50L180 80M100 50L100 8M100 50L100 92" stroke="#fff" stroke-width="1.5"/></svg>`,related:["supernova","neutron-star","kilonova"]},
  {id:"kilonova",icon:"supernova",name_de:"Kilonova",sum_de:"Ein kurzer, heller Ausbruch bei der Verschmelzung zweier Neutronensterne.",exp_de:"Bei der Kollision zweier Neutronensterne entstehen schwere Elemente wie Gold und Platin. Das dabei ausgestoßene Material leuchtet kurz als Kilonova auf. 2017 wurde ein solches Ereignis erstmals mit Gravitationswellen beobachtet.",name_en:"Kilonova",sum_en:"A brief, bright outburst when two neutron stars merge.",exp_en:"When two neutron stars collide, heavy elements such as gold and platinum form. The ejected material briefly glows as a kilonova. In 2017 such an event was observed together with gravitational waves for the first time.",name_es:"Kilonova",sum_es:"Un breve y brillante estallido al fusionarse dos estrellas de neutrones.",exp_es:"Cuando dos estrellas de neutrones chocan se forman elementos pesados como el oro y el platino. El material expulsado brilla brevemente como una kilonova. En 2017 se observó por primera vez un evento así junto con ondas gravitacionales.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="88" cy="50" r="10" fill="#fff"/><circle cx="112" cy="50" r="10" fill="#fff"/><circle cx="100" cy="50" r="22" fill="none" stroke="#fff" opacity=".5"/><path d="M100 24v-8M100 76v8M76 50h-8M124 50h8" stroke="#fff"/></svg>`,related:["neutron-star","gravitational-waves","gamma-ray-burst"]},
  {id:"stellar-wind",icon:"meteor",name_de:"Sternwind",sum_de:"Ein stetiger Strom von Teilchen, den ein Stern in den Raum abgibt.",exp_de:"Sternwinde tragen Masse und Drehimpuls von Sternen fort. Der Sonnenwind ist der Sternwind unserer Sonne. Bei massereichen Sternen können die Winde so stark sein, dass sie die Umgebung formen und die eigene Entwicklung bremsen.",name_en:"Stellar Wind",sum_en:"A steady stream of particles a star releases into space.",exp_en:"Stellar winds carry mass and angular momentum away from stars. The solar wind is the Sun's stellar wind. In massive stars the winds can be strong enough to shape their surroundings and slow their own evolution.",name_es:"Viento Estelar",sum_es:"Un flujo constante de partículas que una estrella libera al espacio.",exp_es:"Los vientos estelares se llevan masa y momento angular de las estrellas. El viento solar es el viento estelar de nuestra estrella. En estrellas masivas los vientos pueden modelar el entorno y frenar su propia evolución.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="40" cy="50" r="16" fill="#fff"/><path d="M66 34h110M66 50h110M66 66h110" stroke="#fff" stroke-dasharray="4 5" opacity=".8"/><circle cx="150" cy="34" r="1.5" fill="#fff"/><circle cx="170" cy="50" r="1.5" fill="#fff"/><circle cx="140" cy="66" r="1.5" fill="#fff"/></svg>`,related:["solar-wind","star","nebula"]},
  {id:"planetary-nebula",icon:"nebula",name_de:"Planetarischer Nebel",sum_de:"Eine leuchtende Gasblase, die ein sterbender Stern abgestoßen hat.",exp_de:"Trotz des Namens haben planetarische Nebel nichts mit Planeten zu tun: Es sind abgestoßene Hüllen von Sternen am Ende ihres Lebens. Der freigelegte heiße Kern regt das Gas zum Leuchten an. Später bleibt nur ein Weißer Zwerg übrig.",name_en:"Planetary Nebula",sum_en:"A glowing bubble of gas shed by a dying star.",exp_en:"Despite the name, planetary nebulae have nothing to do with planets: they are shells thrown off by stars at the end of their lives. The exposed hot core makes the gas glow. In the end only a white dwarf remains.",name_es:"Nebulosa Planetaria",sum_es:"Una burbuja luminosa de gas expulsada por una estrella moribunda.",exp_es:"A pesar del nombre, las nebulosas planetarias no tienen que ver con planetas: son envolturas expulsadas por estrellas al final de su vida. El núcleo caliente expuesto hace brillar el gas. Al final solo queda una enana blanca.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><ellipse cx="100" cy="50" rx="30" ry="22" fill="none" stroke="#fff" stroke-width="3" opacity=".8"/><ellipse cx="100" cy="50" rx="18" ry="13" fill="none" stroke="#fff" stroke-width="1.5" opacity=".5"/><circle cx="100" cy="50" r="4" fill="#fff"/></svg>`,related:["white-dwarf","red-giant","nebula"]},
  {id:"supernova-remnant",icon:"supernova",name_de:"Supernovaüberrest",sum_de:"Die expandierende Gaswolke, die nach einer Supernova zurückbleibt.",exp_de:"Nach der Explosion eines massereichen Sterns breitet sich seine Hülle mit Millionen Kilometern pro Stunde aus. Dabei entstehen heiße Blasen und Stoßwellen. Der Krebsnebel ist der Überrest einer Supernova, die 1054 beobachtet wurde.",name_en:"Supernova Remnant",sum_en:"The expanding cloud of gas left behind by a supernova.",exp_en:"After a massive star explodes, its shell expands at millions of kilometres per hour. This creates hot bubbles and shock waves. The Crab Nebula is the remnant of a supernova seen in 1054.",name_es:"Remanente de Supernova",sum_es:"La nube de gas en expansión que deja una supernova.",exp_es:"Tras la explosión de una estrella masiva, su envoltura se expande a millones de kilómetros por hora. Así se forman burbujas calientes y ondas de choque. La nebulosa del Cangrejo es el remanente de una supernova observada en 1054.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="8" fill="#fff"/><circle cx="100" cy="50" r="22" fill="none" stroke="#fff" opacity=".6"/><circle cx="100" cy="50" r="34" fill="none" stroke="#fff" opacity=".35" stroke-dasharray="3 4"/><path d="M100 28v-8M100 72v8M78 50h-8M122 50h8M84 34l-6-6M116 66l6 6M116 34l6-6M84 66l-6 6" stroke="#fff" stroke-width="1"/></svg>`,related:["supernova","neutron-star","nebula"]},
  {id:"star-cluster",icon:"cluster",name_de:"Sternhaufen",sum_de:"Eine Gruppe von Sternen, die gemeinsam entstanden sind und durch Schwerkraft verbunden bleiben.",exp_de:"Sternhaufen entstehen, wenn viele Sterne zugleich aus derselben Wolke hervorgehen. Man unterscheidet offene Haufen mit jungen Sternen und kugelförmige Haufen mit sehr alten. Sie helfen, Sternentwicklung und Entfernungen zu erforschen.",name_en:"Star Cluster",sum_en:"A group of stars born together and held by gravity.",exp_en:"Star clusters form when many stars emerge at once from the same cloud. Astronomers distinguish open clusters of young stars from globular clusters of very old ones. They help study stellar evolution and distances.",name_es:"Cúmulo Estelar",sum_es:"Un grupo de estrellas nacidas juntas y unidas por la gravedad.",exp_es:"Los cúmulos estelares se forman cuando muchas estrellas surgen a la vez de la misma nube. Se distinguen los cúmulos abiertos, jóvenes, de los globulares, muy antiguos. Ayudan a estudiar la evolución estelar y las distancias.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="80" cy="40" r="4" fill="#fff"/><circle cx="105" cy="34" r="3" fill="#fff"/><circle cx="128" cy="46" r="4.5" fill="#fff"/><circle cx="95" cy="58" r="3.5" fill="#fff"/><circle cx="120" cy="64" r="3" fill="#fff"/><circle cx="70" cy="62" r="3" fill="#fff"/><circle cx="145" cy="60" r="2.5" fill="#fff"/><circle cx="55" cy="48" r="2.5" fill="#fff"/></svg>`,related:["globular-cluster","star-formation","galaxy"]},
  {id:"globular-cluster",icon:"cluster",name_de:"Kugelsternhaufen",sum_de:"Ein kugelförmiger Haufen aus sehr alten Sternen, der eine Galaxie umkreist.",exp_de:"Kugelsternhaufen enthalten hunderttausende Sterne, die fast gleich alt sind. Sie sind bis zu 13 Milliarden Jahre alt und gehören zu den ältesten Objekten der Milchstraße. Ihr Halo umgibt die galaktische Scheibe.",name_en:"Globular Cluster",sum_en:"A spherical swarm of very old stars orbiting a galaxy.",exp_en:"Globular clusters contain hundreds of thousands of stars that are almost equally old. They are up to 13 billion years old and are among the oldest objects of the Milky Way. Their halo surrounds the galactic disk.",name_es:"Cúmulo Globular",sum_es:"Un enjambre esférico de estrellas muy antiguas que orbita una galaxia.",exp_es:"Los cúmulos globulares contienen cientos de miles de estrellas casi de la misma edad. Tienen hasta 13.000 millones de años y están entre los objetos más antiguos de la Vía Láctea. Su halo rodea el disco galáctico.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="26" fill="none" stroke="#fff" stroke-width=".8" opacity=".4"/><circle cx="100" cy="50" r="4" fill="#fff"/><circle cx="85" cy="42" r="2.2" fill="#fff"/><circle cx="114" cy="44" r="2.2" fill="#fff"/><circle cx="92" cy="62" r="2" fill="#fff"/><circle cx="110" cy="60" r="2" fill="#fff"/><circle cx="100" cy="32" r="1.8" fill="#fff"/><circle cx="100" cy="68" r="1.8" fill="#fff"/><circle cx="78" cy="55" r="1.6" fill="#fff"/><circle cx="122" cy="54" r="1.6" fill="#fff"/></svg>`,related:["star-cluster","milky-way","star"]},
  {id:"galaxy-cluster",icon:"galaxy",name_de:"Galaxienhaufen",sum_de:"Ein Verbund aus hunderten bis tausenden Galaxien.",exp_de:"Galaxienhaufen sind die größten gravitativ gebundenen Strukturen im Universum. Zwischen den Galaxien füllt heißes Gas den Raum. Der nächste große Haufen, der Virgo-Haufen, ist rund 65 Millionen Lichtjahre entfernt.",name_en:"Galaxy Cluster",sum_en:"A group of hundreds to thousands of galaxies.",exp_en:"Galaxy clusters are the largest gravitationally bound structures in the universe. Hot gas fills the space between the galaxies. The nearest large cluster, the Virgo Cluster, is about 65 million light-years away.",name_es:"Cúmulo de Galaxias",sum_es:"Un conjunto de cientos o miles de galaxias.",exp_es:"Los cúmulos de galaxias son las mayores estructuras ligadas por gravedad del universo. Un gas caliente llena el espacio entre las galaxias. El gran cúmulo más cercano, el de Virgo, está a unos 65 millones de años luz.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><ellipse cx="70" cy="40" rx="14" ry="5" fill="none" stroke="#fff"/><ellipse cx="130" cy="62" rx="16" ry="6" fill="none" stroke="#fff"/><ellipse cx="120" cy="34" rx="10" ry="4" fill="none" stroke="#fff"/><circle cx="80" cy="66" r="5" fill="none" stroke="#fff"/><circle cx="100" cy="50" r="30" fill="none" stroke="#fff" stroke-width=".6" opacity=".3"/></svg>`,related:["supercluster","galaxy","local-group"]},
  {id:"supercluster",icon:"galaxy",name_de:"Superhaufen",sum_de:"Eine riesige Ansammlung von Galaxienhaufen über hunderte Millionen Lichtjahre.",exp_de:"Superhaufen sind die größten bekannten Strukturen des Kosmos, doch sie halten gravitativ nicht dauerhaft zusammen. Die Milchstraße gehört zum Laniakea-Superhaufen. Im Maßstab der Superhaufen zeigt sich die schwammartige Struktur des Universums.",name_en:"Supercluster",sum_en:"A vast assembly of galaxy clusters spanning hundreds of millions of light-years.",exp_en:"Superclusters are the largest known structures of the cosmos, though they are not permanently bound by gravity. The Milky Way belongs to the Laniakea Supercluster. On this scale the sponge-like structure of the universe becomes visible.",name_es:"Supercúmulo",sum_es:"Una enorme agrupación de cúmulos de galaxias que abarca cientos de millones de años luz.",exp_es:"Los supercúmulos son las mayores estructuras conocidas del cosmos, aunque no permanecen unidos por gravedad de forma duradera. La Vía Láctea pertenece al supercúmulo Laniakea. A esta escala se aprecia la estructura esponjosa del universo.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="40" cy="40" r="6" fill="none" stroke="#fff"/><circle cx="90" cy="60" r="8" fill="none" stroke="#fff"/><circle cx="150" cy="36" r="6" fill="none" stroke="#fff"/><circle cx="160" cy="72" r="5" fill="none" stroke="#fff"/><path d="M46 42l38 16M98 56l46-18M98 64l56 8" stroke="#fff" stroke-dasharray="2 3" opacity=".6"/></svg>`,related:["galaxy-cluster","cosmic-web","galaxy"]},
  {id:"local-group",icon:"galaxy",name_de:"Lokale Gruppe",sum_de:"Die Ansammlung von Galaxien, zu der auch die Milchstraße gehört.",exp_de:"Die Lokale Gruppe umfasst mehr als 50 Galaxien und erstreckt sich über etwa zehn Millionen Lichtjahre. Die beiden größten sind die Milchstraße und Andromeda. In einigen Milliarden Jahren werden beide verschmelzen.",name_en:"Local Group",sum_en:"The collection of galaxies that includes the Milky Way.",exp_en:"The Local Group contains more than 50 galaxies and spans about ten million light-years. Its two largest members are the Milky Way and Andromeda. In a few billion years the two will merge.",name_es:"Grupo Local",sum_es:"El conjunto de galaxias al que pertenece la Vía Láctea.",exp_es:"El Grupo Local reúne más de 50 galaxias y abarca unos diez millones de años luz. Sus dos miembros mayores son la Vía Láctea y Andrómeda. Dentro de unos miles de millones de años se fusionarán.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><ellipse cx="75" cy="50" rx="22" ry="7" fill="none" stroke="#fff" stroke-width="1.5"/><ellipse cx="125" cy="50" rx="22" ry="7" fill="none" stroke="#fff" stroke-width="1.5"/><circle cx="75" cy="50" r="3" fill="#fff"/><circle cx="125" cy="50" r="3" fill="#fff"/><circle cx="40" cy="30" r="2" fill="#fff"/><circle cx="160" cy="70" r="2" fill="#fff"/><circle cx="150" cy="34" r="1.6" fill="#fff"/></svg>`,related:["milky-way","galaxy","supercluster"]},
  {id:"cosmic-web",icon:"galaxy",name_de:"Kosmisches Netz",sum_de:"Die großräumige, netzartige Verteilung von Galaxien im Universum.",exp_de:"Galaxien ordnen sich entlang von Filamenten an, zwischen denen große Leerräume liegen. An den Knoten sitzen Galaxienhaufen und Superhaufen. Diese Struktur bildet sich aus dunkler Materie und Gas seit dem frühen Universum.",name_en:"Cosmic Web",sum_en:"The large-scale, web-like distribution of galaxies in the universe.",exp_en:"Galaxies arrange themselves along filaments, with vast empty voids between them. Galaxy clusters and superclusters sit at the nodes. This structure has grown from dark matter and gas since the early universe.",name_es:"Red Cósmica",sum_es:"La distribución a gran escala, en forma de red, de las galaxias del universo.",exp_es:"Las galaxias se ordenan a lo largo de filamentos, entre los que hay enormes vacíos. En los nodos se sitúan los cúmulos y supercúmulos. Esta estructura se ha formado a partir de materia oscura y gas desde el universo temprano.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M20 30L60 50L40 80M60 50L100 30L140 50L180 30M100 30L110 70L80 80M140 50L110 70M140 50L170 80" fill="none" stroke="#fff" stroke-width="1"/><circle cx="60" cy="50" r="3" fill="#fff"/><circle cx="100" cy="30" r="3" fill="#fff"/><circle cx="140" cy="50" r="3" fill="#fff"/><circle cx="110" cy="70" r="3" fill="#fff"/></svg>`,related:["structure-formation","galaxy-cluster","dark-matter"]},
  {id:"active-galactic-nucleus",icon:"galaxy",name_de:"Aktiver Galaxienkern",sum_de:"Ein heller, energiereicher Kern einer Galaxie, angetrieben von einem Schwarzen Loch.",exp_de:"Fällt Materie auf ein supermassereiches Schwarzes Loch, leuchtet das Zentrum der Galaxie hell auf. Je nach Blickwinkel und Strahlung nennt man solche Objekte Quasar, Blazar oder Seyfert-Galaxie. Sie können das gesamte Umfeld überstrahlen.",name_en:"Active Galactic Nucleus",sum_en:"A bright, energetic galactic core powered by a black hole.",exp_en:"When matter falls onto a supermassive black hole, the galaxy's centre lights up brightly. Depending on the viewing angle and radiation, such objects are called quasars, blazars or Seyfert galaxies. They can outshine their entire surroundings.",name_es:"Núcleo Activo de Galaxia",sum_es:"Un núcleo galáctico brillante y energético impulsado por un agujero negro.",exp_es:"Cuando la materia cae sobre un agujero negro supermasivo, el centro de la galaxia brilla intensamente. Según el ángulo de visión y la radiación, estos objetos se llaman cuásares, blázares o galaxias Seyfert. Pueden superar en brillo a todo su entorno.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="6" fill="#fff"/><ellipse cx="100" cy="50" rx="30" ry="9" fill="none" stroke="#fff"/><path d="M100 44V14M100 56v30" stroke="#fff" stroke-width="3"/><circle cx="100" cy="50" r="16" fill="none" stroke="#fff" opacity=".4"/></svg>`,related:["quasar","blackhole","accretion-disk"]},
  {id:"spiral-galaxy",icon:"galaxy",name_de:"Spiralgalaxie",sum_de:"Eine Galaxie mit einer flachen Scheibe und spiraligen Armen.",exp_de:"In den Spiralarmen liegen viel Gas und junge, helle Sterne. Die Milchstraße und Andromeda sind Spiralgalaxien. Ihre Rotation verrät, dass viel unsichtbare dunkle Materie sie zusammenhält.",name_en:"Spiral Galaxy",sum_en:"A galaxy with a flat disk and spiral arms.",exp_en:"The spiral arms contain lots of gas and young, bright stars. The Milky Way and Andromeda are spiral galaxies. Their rotation reveals that a lot of invisible dark matter holds them together.",name_es:"Galaxia Espiral",sum_es:"Una galaxia con un disco plano y brazos espirales.",exp_es:"En los brazos espirales hay mucho gas y estrellas jóvenes y brillantes. La Vía Láctea y Andrómeda son galaxias espirales. Su rotación revela que una gran cantidad de materia oscura invisible las mantiene unidas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="5" fill="#fff"/><path d="M100 50c8-12 26-16 40-6s10 30-6 34-36-6-42-22" fill="none" stroke="#fff" stroke-width="2"/><path d="M100 50c-8 12-26 16-40 6s-10-30 6-34 36 6 42 22" fill="none" stroke="#fff" stroke-width="2"/></svg>`,related:["galaxy","milky-way","elliptical-galaxy"]},
  {id:"elliptical-galaxy",icon:"galaxy",name_de:"Elliptische Galaxie",sum_de:"Eine glatte, elliptisch geformte Galaxie mit wenig Gas und alten Sternen.",exp_de:"Elliptische Galaxien reichen von kugelrund bis stark länglich und bestehen meist aus alten Sternen. Sie entstehen oft durch die Verschmelzung von Spiralgalaxien. Ihr weniges Gas bedeutet, dass kaum neue Sterne gebildet werden.",name_en:"Elliptical Galaxy",sum_en:"A smooth, elliptical galaxy with little gas and old stars.",exp_en:"Elliptical galaxies range from round to strongly elongated and consist mostly of old stars. They often form through the merger of spiral galaxies. Their scarce gas means few new stars form.",name_es:"Galaxia Elíptica",sum_es:"Una galaxia lisa y elíptica con poco gas y estrellas antiguas.",exp_es:"Las galaxias elípticas van de redondas a muy alargadas y constan sobre todo de estrellas antiguas. A menudo se forman por la fusión de galaxias espirales. Su escaso gas implica que apenas nacen estrellas nuevas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><ellipse cx="100" cy="50" rx="46" ry="26" fill="none" stroke="#fff" stroke-width="1.5"/><ellipse cx="100" cy="50" rx="24" ry="14" fill="none" stroke="#fff" opacity=".6"/><circle cx="100" cy="50" r="5" fill="#fff"/></svg>`,related:["galaxy","spiral-galaxy","galaxy-cluster"]},
  {id:"dwarf-galaxy",icon:"galaxy",name_de:"Zwerggalaxie",sum_de:"Eine kleine Galaxie mit vergleichsweise wenigen Sternen.",exp_de:"Zwerggalaxien enthalten oft nur Millionen statt Milliarden Sterne. Viele umkreisen als Begleiter größere Galaxien, wie die Magellanschen Wolken die Milchstraße. Sie können im Laufe der Zeit von ihrer großen Nachbarin verschluckt werden.",name_en:"Dwarf Galaxy",sum_en:"A small galaxy with comparatively few stars.",exp_en:"Dwarf galaxies often contain only millions rather than billions of stars. Many orbit larger galaxies as companions, such as the Magellanic Clouds around the Milky Way. Over time they can be swallowed by their larger neighbour.",name_es:"Galaxia Enana",sum_es:"Una galaxia pequeña con relativamente pocas estrellas.",exp_es:"Las galaxias enanas suelen contener solo millones de estrellas en lugar de miles de millones. Muchas orbitan galaxias mayores como compañeras, como las nubes de Magallanes alrededor de la Vía Láctea. Con el tiempo pueden ser absorbidas por su vecina mayor.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><ellipse cx="70" cy="50" rx="34" ry="14" fill="none" stroke="#fff" stroke-width="1.2" opacity=".6"/><circle cx="70" cy="50" r="4" fill="#fff" opacity=".6"/><ellipse cx="150" cy="50" rx="18" ry="9" fill="none" stroke="#fff" stroke-width="1.5"/><circle cx="150" cy="50" r="2.5" fill="#fff"/></svg>`,related:["galaxy","milky-way","local-group"]},
  {id:"expansion",icon:"redshift",name_de:"Expansion des Universums",sum_de:"Die Ausdehnung des Raums, durch die sich Galaxien voneinander entfernen.",exp_de:"Der Raum selbst dehnt sich aus, sodass weit entfernte Galaxien sich schneller von uns entfernen. Das zeigt sich an der Rotverschiebung ihres Lichts. Seit etwa fünf Milliarden Jahren läuft die Expansion beschleunigt ab.",name_en:"Expansion of the Universe",sum_en:"The stretching of space that carries galaxies apart.",exp_en:"Space itself expands, so distant galaxies move away from us faster. This shows as a redshift in their light. For about five billion years the expansion has been accelerating.",name_es:"Expansión del Universo",sum_es:"La expansión del espacio que aleja a las galaxias entre sí.",exp_es:"El propio espacio se expande, de modo que las galaxias lejanas se alejan de nosotros más rápido. Esto se ve en el corrimiento al rojo de su luz. Desde hace unos cinco mil millones de años la expansión se acelera.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="4" fill="#fff"/><circle cx="60" cy="50" r="3" fill="#fff"/><circle cx="140" cy="50" r="3" fill="#fff"/><circle cx="30" cy="50" r="2.5" fill="#fff" opacity=".7"/><circle cx="170" cy="50" r="2.5" fill="#fff" opacity=".7"/><path d="M104 50h32M96 50H64M136 50h30M64 50H34" stroke="#fff" stroke-dasharray="3 3" opacity=".5"/></svg>`,related:["redshift","dark-energy","big-bang"]},
  {id:"hubble-constant",icon:"lightyear",name_de:"Hubble-Konstante",sum_de:"Der heutige Wert der Expansionsgeschwindigkeit des Universums.",exp_de:"Die Hubble-Konstante gibt an, wie schnell sich der Raum pro Entfernungsabschnitt heute ausdehnt. Verschiedene Messmethoden liefern derzeit Werte, die nicht ganz zusammenpassen, die Hubble-Spannung. Sie liegt bei rund 70 Kilometern pro Sekunde und Megaparsec.",name_en:"Hubble Constant",sum_en:"The present-day rate of cosmic expansion.",exp_en:"The Hubble constant tells how fast space expands today per unit of distance. Different measurement methods currently give values that do not quite agree, the Hubble tension. It is about 70 kilometres per second per megaparsec.",name_es:"Constante de Hubble",sum_es:"El valor actual de la velocidad de expansión del universo.",exp_es:"La constante de Hubble indica a qué velocidad se expande hoy el espacio por unidad de distancia. Distintos métodos de medición dan valores que no coinciden del todo, una discrepancia llamada tensión de Hubble. Ronda los 70 kilómetros por segundo y megapársec.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="30" cy="60" r="3" fill="#fff"/><circle cx="100" cy="45" r="3" fill="#fff"/><circle cx="170" cy="30" r="3" fill="#fff"/><path d="M30 60L170 30" stroke="#fff" stroke-dasharray="3 4" opacity=".6"/><path d="M150 36l14-4-2 12" fill="none" stroke="#fff"/></svg>`,related:["expansion","redshift","dark-energy"]},
  {id:"cosmic-inflation",icon:"supernova",name_de:"Kosmische Inflation",sum_de:"Eine extrem kurze Phase enormer Ausdehnung direkt nach dem Urknall.",exp_de:"In den ersten Sekundenbruchteilen soll sich das junge Universum um ein Vielfaches ausgedehnt haben. Diese Inflation erklärt, warum der Raum so flach und die Hintergrundstrahlung so gleichmäßig ist. Sie ist bislang ein Modell, das zu den Beobachtungen passt.",name_en:"Cosmic Inflation",sum_en:"An extremely brief phase of enormous expansion just after the Big Bang.",exp_en:"In the first tiny fraction of a second the young universe is thought to have expanded enormously. Inflation explains why space is so flat and the background radiation so even. It remains a model that fits the observations.",name_es:"Inflación Cósmica",sum_es:"Una fase brevísima de enorme expansión justo después del Big Bang.",exp_es:"En la primera fracción diminuta de segundo, el universo joven se habría expandido enormemente. La inflación explica por qué el espacio es tan plano y la radiación de fondo tan uniforme. Sigue siendo un modelo que encaja con las observaciones.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="4" fill="#fff"/><circle cx="100" cy="50" r="12" fill="none" stroke="#fff" opacity=".7"/><circle cx="100" cy="50" r="24" fill="none" stroke="#fff" opacity=".5"/><circle cx="100" cy="50" r="38" fill="none" stroke="#fff" opacity=".3" stroke-dasharray="3 4"/></svg>`,related:["big-bang","expansion","cosmic-background"]},
  {id:"structure-formation",icon:"galaxy",name_de:"Strukturbildung",sum_de:"Die Entstehung von Galaxien und großen Strukturen aus kleinen Dichteschwankungen.",exp_de:"Schon im frühen Universum gab es winzige Unterschiede in der Dichte. Die Schwerkraft verstärkte sie über Milliarden Jahre zu Filamenten, Galaxien und Haufen. Computermodelle bilden diesen Prozess nach.",name_en:"Structure Formation",sum_en:"The growth of galaxies and large structures from small density fluctuations.",exp_en:"Even in the early universe there were tiny differences in density. Over billions of years gravity amplified them into filaments, galaxies and clusters. Computer models reproduce this process.",name_es:"Formación de Estructuras",sum_es:"La formación de galaxias y grandes estructuras a partir de pequeñas fluctuaciones de densidad.",exp_es:"Ya en el universo temprano había mínimas diferencias de densidad. Durante miles de millones de años la gravedad las amplificó hasta formar filamentos, galaxias y cúmulos. Los modelos por computadora reproducen este proceso.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="40" cy="30" r="1.2" fill="#fff"/><circle cx="60" cy="40" r="1.4" fill="#fff"/><circle cx="100" cy="30" r="1.6" fill="#fff"/><circle cx="140" cy="40" r="1.6" fill="#fff"/><circle cx="160" cy="30" r="1.6" fill="#fff"/><circle cx="80" cy="70" r="2" fill="#fff"/><circle cx="120" cy="70" r="2.2" fill="#fff"/><circle cx="100" cy="55" r="3" fill="#fff"/><circle cx="50" cy="60" r="2.6" fill="#fff"/><circle cx="150" cy="62" r="2.4" fill="#fff"/></svg>`,related:["cosmic-web","dark-matter","galaxy"]},
  {id:"standard-candle",icon:"supernova",name_de:"Standardkerze",sum_de:"Ein Objekt bekannter Leuchtkraft, mit dem sich Entfernungen messen lassen.",exp_de:"Kennt man die wahre Helligkeit eines Objekts und misst seine scheinbare Helligkeit, lässt sich die Entfernung berechnen. Cepheiden und Typ-Ia-Supernovae dienen als solche Standardkerzen. Mit ihnen wurde die beschleunigte Expansion entdeckt.",name_en:"Standard Candle",sum_en:"An object of known luminosity used to measure distances.",exp_en:"If the true brightness of an object is known and its apparent brightness measured, the distance follows. Cepheids and type Ia supernovae serve as such standard candles. They revealed the accelerating expansion.",name_es:"Vela Estándar",sum_es:"Un objeto de luminosidad conocida que sirve para medir distancias.",exp_es:"Si se conoce el brillo real de un objeto y se mide su brillo aparente, se obtiene la distancia. Las cefeidas y las supernovas de tipo Ia sirven como velas estándar. Con ellas se descubrió la expansión acelerada.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="40" cy="50" r="6" fill="#fff"/><path d="M46 46l14-8M46 50h16M46 54l14 8" stroke="#fff" stroke-width="1" opacity=".7"/><path d="M60 50h110" stroke="#fff" stroke-dasharray="4 4"/><path d="M160 44v12M120 44v12" stroke="#fff"/></svg>`,related:["cepheid","supernova","expansion"]},
  {id:"accretion-disk",icon:"blackhole",name_de:"Akkretionsscheibe",sum_de:"Eine rotierende Scheibe aus Materie, die auf ein kompaktes Objekt fällt.",exp_de:"Fällt Gas und Staub auf ein Schwarzes Loch oder einen Neutronenstern, bildet sich eine Scheibe. Durch Reibung wird sie extrem heiß und strahlt oft heller als der Rest der Galaxie. Aus ihren inneren Bereichen können Jets hervorschießen.",name_en:"Accretion Disk",sum_en:"A rotating disk of matter falling onto a compact object.",exp_en:"When gas and dust fall onto a black hole or neutron star, a disk forms. Friction makes it extremely hot and it often shines brighter than the rest of the galaxy. Jets can shoot out from its inner region.",name_es:"Disco de Acreción",sum_es:"Un disco giratorio de materia que cae sobre un objeto compacto.",exp_es:"Cuando gas y polvo caen sobre un agujero negro o una estrella de neutrones, se forma un disco. La fricción lo calienta muchísimo y a menudo brilla más que el resto de la galaxia. De su zona interior pueden salir chorros.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><ellipse cx="100" cy="50" rx="52" ry="16" fill="none" stroke="#fff" stroke-width="1.5"/><ellipse cx="100" cy="50" rx="36" ry="11" fill="none" stroke="#fff" opacity=".6"/><circle cx="100" cy="50" r="8" fill="#000" stroke="#fff" stroke-width="2"/></svg>`,related:["blackhole","event-horizon","quasar"]},
  {id:"spacetime",icon:"blackhole",name_de:"Raumzeit",sum_de:"Die Verbindung von Raum und Zeit zu einem vierdimensionalen Gefüge.",exp_de:"In der Relativitätstheorie sind Raum und Zeit untrennbar verbunden. Massen und Energie krümmen dieses Gefüge, und was wir Gravitation nennen, ist die Bewegung entlang dieser Krümmung. Licht folgt derselben gekrümmten Bahn.",name_en:"Spacetime",sum_en:"The union of space and time into a four-dimensional fabric.",exp_en:"In relativity, space and time are inseparably linked. Mass and energy curve this fabric, and what we call gravity is motion along that curvature. Light follows the same curved path.",name_es:"Espacio-tiempo",sum_es:"La unión de espacio y tiempo en un tejido tetradimensional.",exp_es:"En la relatividad, espacio y tiempo están unidos de forma inseparable. La masa y la energía curvan ese tejido, y lo que llamamos gravedad es el movimiento a lo largo de esa curvatura. La luz sigue la misma trayectoria curvada.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M20 20h160M20 40h160M20 60h160M20 80h160" stroke="#fff" opacity=".4"/><ellipse cx="100" cy="55" rx="26" ry="9" fill="none" stroke="#fff"/><ellipse cx="100" cy="55" rx="14" ry="5" fill="none" stroke="#fff" opacity=".6"/><circle cx="100" cy="50" r="7" fill="#fff"/></svg>`,related:["relativity","gravity","blackhole"]},
  {id:"multiverse",icon:"galaxy",name_de:"Multiversum",sum_de:"Die hypothetische Gesamtheit vieler möglicher Universen.",exp_de:"Einige kosmologische Modelle legen nahe, dass unser Universum nur eines von vielen sein könnte. Belege dafür gibt es bislang nicht, die Idee ist umstritten. Sie knüpft an die Inflation und an die Quantenmechanik an.",name_en:"Multiverse",sum_en:"The hypothetical totality of many possible universes.",exp_en:"Some cosmological models suggest that our universe could be only one of many. There is no evidence for this yet and the idea is debated. It connects to inflation and to quantum mechanics.",name_es:"Multiverso",sum_es:"La totalidad hipotética de muchos universos posibles.",exp_es:"Algunos modelos cosmológicos sugieren que nuestro universo podría ser solo uno de muchos. Por ahora no hay pruebas y la idea es discutida. Se relaciona con la inflación y la mecánica cuántica.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="70" cy="50" r="26" fill="none" stroke="#fff" stroke-width="1.2"/><circle cx="110" cy="44" r="22" fill="none" stroke="#fff" opacity=".7"/><circle cx="140" cy="58" r="18" fill="none" stroke="#fff" opacity=".5"/><circle cx="70" cy="50" r="3" fill="#fff"/><circle cx="110" cy="44" r="2.5" fill="#fff"/></svg>`,related:["big-bang","cosmic-inflation","cosmic-background"]},
  {id:"dark-ages",icon:"nebula",name_de:"Dunkles Zeitalter",sum_de:"Die Zeit im frühen Universum, bevor die ersten Sterne leuchteten.",exp_de:"Nach dem Urknall und vor der Bildung der ersten Sterne war das Universum von dichtem, neutralem Gas erfüllt. Es gab keine Lichtquellen, daher der Name. Erst die ersten Galaxien beendeten diese dunkle Phase.",name_en:"Cosmic Dark Ages",sum_en:"The era in the early universe before the first stars shone.",exp_en:"After the Big Bang and before the first stars formed, the universe was filled with dense, neutral gas. There were no sources of light, hence the name. Only the first galaxies ended this dark phase.",name_es:"Edad Oscura",sum_es:"La época del universo temprano antes de que brillaran las primeras estrellas.",exp_es:"Tras el Big Bang y antes de formarse las primeras estrellas, el universo estaba lleno de gas neutro y denso. No había fuentes de luz, de ahí el nombre. Solo las primeras galaxias pusieron fin a esta fase oscura.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><ellipse cx="100" cy="50" rx="78" ry="34" fill="none" stroke="#fff" stroke-width="1" opacity=".4"/><circle cx="130" cy="40" r="5" fill="#fff"/><path d="M130 30v-6M130 56v6M120 40h-6M140 40h6" stroke="#fff" stroke-width="1.5"/></svg>`,related:["big-bang","star-formation","cosmic-background"]},
  {id:"relativity",icon:"orbit",name_de:"Relativitätstheorie",sum_de:"Einsteins Theorie von Raum, Zeit, Gravitation und Bewegung.",exp_de:"Die spezielle Relativitätstheorie verknüpft Raum und Zeit und zeigt, dass die Lichtgeschwindigkeit die Grenze ist. Die allgemeine Relativitätstheorie deutet Gravitation als Krümmung der Raumzeit. Beide sind vielfach bestätigt.",name_en:"Theory of Relativity",sum_en:"Einstein's theory of space, time, gravity and motion.",exp_en:"Special relativity links space and time and shows that the speed of light is the limit. General relativity interprets gravity as the curvature of spacetime. Both are confirmed in many ways.",name_es:"Teoría de la Relatividad",sum_es:"La teoría de Einstein sobre espacio, tiempo, gravedad y movimiento.",exp_es:"La relatividad especial une espacio y tiempo y muestra que la velocidad de la luz es el límite. La relatividad general interpreta la gravedad como curvatura del espacio-tiempo. Ambas están confirmadas de muchas formas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M100 50L60 14M100 50L140 14M100 50L60 86M100 50L140 86" stroke="#fff" stroke-width="1" opacity=".7"/><circle cx="100" cy="50" r="7" fill="#fff"/><ellipse cx="100" cy="50" rx="34" ry="10" fill="none" stroke="#fff" opacity=".4"/></svg>`,related:["spacetime","gravity","light-speed"]},
  {id:"light-speed",icon:"lightyear",name_de:"Lichtgeschwindigkeit",sum_de:"Die höchste Geschwindigkeit, mit der sich Signale im Vakuum ausbreiten.",exp_de:"Licht legt im Vakuum fast 300.000 Kilometer pro Sekunde zurück. Diese Grenze gilt für alle Informationen und nicht nur für sichtbares Licht. Sie macht interstellare Reisen extrem langsam.",name_en:"Speed of Light",sum_en:"The highest speed at which signals travel through a vacuum.",exp_en:"Light travels almost 300,000 kilometres per second in a vacuum. This limit applies to all information, not only visible light. It makes interstellar travel extremely slow.",name_es:"Velocidad de la Luz",sum_es:"La máxima velocidad a la que se propagan las señales en el vacío.",exp_es:"La luz recorre casi 300.000 kilómetros por segundo en el vacío. Este límite vale para toda la información, no solo para la luz visible. Hace que los viajes interestelares sean extremadamente lentos.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="30" cy="50" r="8" fill="#fff"/><path d="M42 50h130" stroke="#fff" stroke-width="2" stroke-dasharray="8 4"/><path d="M172 42l12 8-12 8" fill="none" stroke="#fff" stroke-width="2"/></svg>`,related:["photon","lightyear","time-dilation"]},
  {id:"time-dilation",icon:"orbit",name_de:"Zeitdilatation",sum_de:"Dass die Zeit für schnell bewegte oder stark gravitierte Körper langsamer vergeht.",exp_de:"Bewegt sich eine Uhr sehr schnell oder liegt sie in einem starken Gravitationsfeld, tickt sie langsamer als eine unbewegte Uhr weit entfernt. Satellitennavigation muss diesen Effekt laufend korrigieren. Er ist experimentell bestätigt.",name_en:"Time Dilation",sum_en:"The slowing of time for fast-moving or strongly gravitated bodies.",exp_en:"A clock moving very fast, or sitting in a strong gravitational field, ticks more slowly than a distant stationary one. Satellite navigation must constantly correct for this effect. It is experimentally confirmed.",name_es:"Dilatación del Tiempo",sum_es:"Que el tiempo transcurre más despacio para cuerpos rápidos o muy gravitados.",exp_es:"Un reloj que se mueve muy rápido, o que está en un campo gravitatorio intenso, avanza más despacio que otro lejano y en reposo. La navegación por satélite debe corregir continuamente este efecto. Está confirmado experimentalmente.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="60" cy="50" r="20" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M60 50V36M60 50l12 8" stroke="#fff"/><circle cx="140" cy="50" r="20" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M140 50V40M140 50l8 6" stroke="#fff" opacity=".6"/><path d="M90 50h30" stroke="#fff" stroke-dasharray="3 3" opacity=".5"/></svg>`,related:["relativity","light-speed","spacetime"]},
  {id:"gravitational-lensing",icon:"galaxy",name_de:"Gravitationslinsen",sum_de:"Die Ablenkung von Licht durch die Schwerkraft massereicher Objekte.",exp_de:"Eine große Masse krümmt die Raumzeit und lenkt das Licht dahinterliegender Objekte ab. So können Galaxien vergrößert oder zu Ringen und Bögen verzerrt erscheinen. Aus diesen Mustern lässt sich auf dunkle Materie schließen.",name_en:"Gravitational Lensing",sum_en:"The bending of light by the gravity of massive objects.",exp_en:"A large mass curves spacetime and deflects the light of objects behind it. As a result, galaxies can appear magnified or distorted into rings and arcs. These patterns reveal dark matter.",name_es:"Lente Gravitacional",sum_es:"La desviación de la luz por la gravedad de objetos masivos.",exp_es:"Una gran masa curva el espacio-tiempo y desvía la luz de los objetos que hay detrás. Así, las galaxias pueden aparecer ampliadas o deformadas en anillos y arcos. Estos patrones revelan la materia oscura.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="10" fill="#fff"/><path d="M10 50c30-26 60-26 90 0s60 26 90 0" fill="none" stroke="#fff" stroke-width="1.2" opacity=".7"/><path d="M10 50c30 26 60 26 90 0s60-26 90 0" fill="none" stroke="#fff" stroke-width="1.2" opacity=".4"/></svg>`,related:["gravity","dark-matter","relativity"]},
  {id:"hawking-radiation",icon:"blackhole",name_de:"Hawking-Strahlung",sum_de:"Die theoretische Strahlung, durch die Schwarze Löcher langsam Masse verlieren.",exp_de:"Nach Stephen Hawking können am Rand eines Schwarzen Lochs Teilchenpaare entstehen, von denen eines entkommt. Dadurch verliert das Loch winzige Mengen an Masse und könnte über sehr lange Zeit verdampfen. Nachgewiesen ist der Effekt noch nicht.",name_en:"Hawking Radiation",sum_en:"The theoretical radiation by which black holes slowly lose mass.",exp_en:"According to Stephen Hawking, pairs of particles can arise at the edge of a black hole, one of which escapes. This makes the hole lose tiny amounts of mass and it could evaporate over extremely long times. The effect has not yet been observed.",name_es:"Radiación de Hawking",sum_es:"La radiación teórica por la que los agujeros negros pierden masa lentamente.",exp_es:"Según Stephen Hawking, en el borde de un agujero negro pueden surgir pares de partículas y una de ellas escapa. Así el agujero pierde cantidades mínimas de masa y podría evaporarse tras tiempos enormes. El efecto aún no se ha observado.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="16" fill="#000" stroke="#fff" stroke-width="2"/><circle cx="100" cy="50" r="30" fill="none" stroke="#fff" opacity=".4" stroke-dasharray="3 4"/><path d="M70 30l-12-10M130 30l12-10M70 70l-12 10M130 70l12 10" stroke="#fff" stroke-width="1.2"/></svg>`,related:["blackhole","event-horizon","singularitaet"]},
  {id:"antimatter",icon:"singularitaet",name_de:"Antimaterie",sum_de:"Materie aus Antiteilchen, die bei Kontakt mit normaler Materie zerstrahlt.",exp_de:"Zu jedem Teilchen gibt es ein Antiteilchen mit entgegengesetzter Ladung. Treffen beide aufeinander, vernichten sie sich und setzen reine Energie frei. Im frühen Universum sollte es fast gleich viel von beidem gegeben haben, doch heute überwiegt die normale Materie.",name_en:"Antimatter",sum_en:"Matter made of antiparticles that annihilates on contact with ordinary matter.",exp_en:"Every particle has an antiparticle with the opposite charge. When the two meet they annihilate and release pure energy. In the early universe there should have been almost equal amounts of both, yet today ordinary matter dominates.",name_es:"Antimateria",sum_es:"Materia hecha de antipartículas que se aniquila al contacto con la materia normal.",exp_es:"Cada partícula tiene una antipartícula con carga opuesta. Cuando ambas se encuentran, se aniquilan y liberan energía pura. En el universo temprano debía haber casi la misma cantidad de las dos, pero hoy predomina la materia normal.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="60" cy="50" r="12" fill="none" stroke="#fff" stroke-width="1.5"/><circle cx="140" cy="50" r="12" fill="#fff"/><path d="M74 50h52" stroke="#fff" stroke-dasharray="4 4"/><path d="M92 40l16 20M108 40l-16 20" stroke="#fff" stroke-width="1.5"/></svg>`,related:["big-bang","singularitaet","cosmic-ray"]},
  {id:"plasma",icon:"sun",name_de:"Plasma",sum_de:"Ein heißes Gas aus geladenen Teilchen, der häufigste Zustand sichtbarer Materie.",exp_de:"Bei sehr hohen Temperaturen zerfallen Atome in freie Elektronen und Ionen. Dieses Plasma leitet Strom und reagiert auf Magnetfelder. Sterne, Blitze und Polarlichter bestehen aus Plasma.",name_en:"Plasma",sum_en:"A hot gas of charged particles, the most common state of visible matter.",exp_en:"At very high temperatures atoms break into free electrons and ions. This plasma conducts electricity and responds to magnetic fields. Stars, lightning and the aurora are made of plasma.",name_es:"Plasma",sum_es:"Un gas caliente de partículas cargadas, el estado más común de la materia visible.",exp_es:"A temperaturas muy altas los átomos se separan en electrones libres e iones. Este plasma conduce la electricidad y reacciona a los campos magnéticos. Las estrellas, los rayos y las auroras están hechos de plasma.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="70" cy="40" r="3" fill="#fff"/><circle cx="110" cy="60" r="2.5" fill="#fff"/><circle cx="140" cy="38" r="2" fill="#fff"/><circle cx="90" cy="70" r="2" fill="#fff"/><path d="M70 40q20-14 40 20t30-22" fill="none" stroke="#fff" stroke-width="1" opacity=".6"/><path d="M50 66q26 10 52-6t44 4" fill="none" stroke="#fff" stroke-width="1" opacity=".4"/></svg>`,related:["sun","solar-wind","aurora"]},
  {id:"electromagnetic-spectrum",icon:"lightyear",name_de:"Elektromagnetisches Spektrum",sum_de:"Die Gesamtheit aller Strahlungsarten von Radiowellen bis Gammastrahlung.",exp_de:"Licht ist nur ein kleiner Ausschnitt der elektromagnetischen Strahlung. Dazu gehören auch Radio-, Mikro-, Infrarot-, Ultra-violett-, Röntgen- und Gammastrahlung. Alle breiten sich mit Lichtgeschwindigkeit aus und unterscheiden sich nur in der Wellenlänge.",name_en:"Electromagnetic Spectrum",sum_en:"The full range of radiation from radio waves to gamma rays.",exp_en:"Light is only a small part of electromagnetic radiation. It also includes radio, microwave, infrared, ultraviolet, X-ray and gamma radiation. All travel at the speed of light and differ only in wavelength.",name_es:"Espectro Electromagnético",sum_es:"El conjunto de todas las radiaciones, desde ondas de radio hasta rayos gamma.",exp_es:"La luz es solo una pequeña parte de la radiación electromagnética. También incluye radio, microondas, infrarrojo, ultravioleta, rayos X y rayos gamma. Todas se propagan a la velocidad de la luz y solo difieren en la longitud de onda.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M15 50q10-18 20 0t20 0 20 0 20 0 20 0 20 0 20 0" fill="none" stroke="#fff" stroke-width="1.4"/><path d="M15 72h170" stroke="#fff" opacity=".5"/><path d="M15 66v12M100 66v12M185 66v12" stroke="#fff" opacity=".5"/></svg>`,related:["light-speed","photon","spectroscopy"]},
  {id:"doppler-effect",icon:"pulsar",name_de:"Doppler-Effekt",sum_de:"Die Verschiebung von Wellen, wenn sich Quelle und Beobachter bewegen.",exp_de:"Nähert sich eine Schall- oder Lichtquelle, wird die Wellenlänge kürzer, entfernt sie sich, länger. Bei Licht zeigt sich das als Blau- oder Rotverschiebung. So lassen sich Geschwindigkeiten von Sternen und Galaxien messen.",name_en:"Doppler Effect",sum_en:"The shift of waves when source and observer move relative to each other.",exp_en:"When a source of sound or light approaches, the wavelength shortens; when it recedes, it lengthens. For light this appears as a blue or red shift. It lets us measure the speeds of stars and galaxies.",name_es:"Efecto Doppler",sum_es:"El desplazamiento de las ondas cuando la fuente y el observador se mueven.",exp_es:"Cuando una fuente de sonido o luz se acerca, la longitud de onda se acorta; cuando se aleja, se alarga. En la luz esto se ve como desplazamiento al azul o al rojo. Permite medir las velocidades de estrellas y galaxias.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="60" cy="50" r="6" fill="#fff"/><path d="M78 30q30 20 0 40M92 22q44 28 0 56M106 14q58 36 0 72" fill="none" stroke="#fff" opacity=".7"/><path d="M150 38h30M150 50h24M150 62h18" stroke="#fff"/></svg>`,related:["redshift","pulsar","spectroscopy"]},
  {id:"cosmic-ray",icon:"singularitaet",name_de:"Kosmische Strahlung",sum_de:"Hochenergetische Teilchen, die aus dem Weltall auf die Erde treffen.",exp_de:"Kosmische Strahlung besteht aus Atomkernen und Elementarteilchen mit sehr hoher Energie. Ein Teil stammt von der Sonne, ein Teil aus Supernova-Überresten und fernen Galaxien. Auf die Atmosphäre treffend, löst sie ausgedehnte Teilchenschauer aus.",name_en:"Cosmic Rays",sum_en:"High-energy particles from space that strike the Earth.",exp_en:"Cosmic rays consist of atomic nuclei and elementary particles of very high energy. Some come from the Sun, some from supernova remnants and distant galaxies. Hitting the atmosphere, they trigger extensive particle showers.",name_es:"Rayos Cósmicos",sum_es:"Partículas de alta energía procedentes del espacio que llegan a la Tierra.",exp_es:"Los rayos cósmicos son núcleos atómicos y partículas elementales de muy alta energía. Una parte viene del Sol y otra de restos de supernova y galaxias lejanas. Al chocar con la atmósfera, producen amplias cascadas de partículas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M40 10l14 22-8 6 12 20" fill="none" stroke="#fff" stroke-width="1.4"/><path d="M120 8l-10 24 8 6-14 22" fill="none" stroke="#fff" stroke-width="1.4" opacity=".7"/><path d="M20 84h160M20 78v12M180 78v12" stroke="#fff" opacity=".5"/></svg>`,related:["solar-wind","supernova","atmosphere"]},
  {id:"interstellar-medium",icon:"nebula",name_de:"Interstellares Medium",sum_de:"Die dünne Materie und Strahlung zwischen den Sternen einer Galaxie.",exp_de:"Zwischen den Sternen ist es nicht leer: Es gibt Gas, Staub und Strahlung, wenn auch extrem dünn. Aus diesem Medium entstehen neue Sterne, und Supernovae reichern es mit schweren Elementen an. Es füllt den größten Teil des Volumens einer Galaxie.",name_en:"Interstellar Medium",sum_en:"The thin matter and radiation between the stars of a galaxy.",exp_en:"The space between stars is not empty: it holds gas, dust and radiation, though extremely thin. New stars form from this medium, and supernovae enrich it with heavy elements. It fills most of a galaxy's volume.",name_es:"Medio Interestelar",sum_es:"La tenue materia y radiación entre las estrellas de una galaxia.",exp_es:"El espacio entre las estrellas no está vacío: contiene gas, polvo y radiación, aunque muy tenues. De este medio nacen nuevas estrellas y las supernovas lo enriquecen con elementos pesados. Ocupa la mayor parte del volumen de una galaxia.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="40" cy="30" r="1.5" fill="#fff"/><circle cx="80" cy="60" r="1.5" fill="#fff"/><circle cx="120" cy="34" r="1.5" fill="#fff"/><circle cx="160" cy="64" r="1.5" fill="#fff"/><circle cx="100" cy="50" r="2" fill="#fff"/><path d="M25 50q35-20 70 0t80 0" fill="none" stroke="#fff" opacity=".3" stroke-dasharray="3 4"/></svg>`,related:["molecular-cloud","star-formation","nebula"]},
  {id:"molecular-cloud",icon:"nebula",name_de:"Molekülwolke",sum_de:"Eine kalte, dichte Wolke aus Gas und Staub, in der Sterne entstehen.",exp_de:"Molekülwolken sind die kältesten und dichtesten Regionen des interstellaren Mediums. In ihnen verbinden sich Atome zu Molekülen, vor allem Wasserstoff. Wo sie unter der eigenen Schwerkraft zusammenbrechen, zünden neue Sterne.",name_en:"Molecular Cloud",sum_en:"A cold, dense cloud of gas and dust where stars are born.",exp_en:"Molecular clouds are the coldest and densest regions of the interstellar medium. Within them atoms join into molecules, above all hydrogen. Where they collapse under their own gravity, new stars ignite.",name_es:"Nube Molecular",sum_es:"Una nube fría y densa de gas y polvo donde nacen las estrellas.",exp_es:"Las nubes moleculares son las regiones más frías y densas del medio interestelar. En ellas los átomos se unen en moléculas, sobre todo de hidrógeno. Donde colapsan por su propia gravedad, se encienden nuevas estrellas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><ellipse cx="70" cy="50" rx="38" ry="24" fill="none" stroke="#fff" stroke-width="1.2" opacity=".7"/><ellipse cx="130" cy="52" rx="32" ry="20" fill="none" stroke="#fff" opacity=".5"/><circle cx="80" cy="48" r="3" fill="#fff"/><circle cx="118" cy="54" r="2.5" fill="#fff"/></svg>`,related:["star-formation","interstellar-medium","accretion-disk"]},
  {id:"tidal-force",icon:"orbit",name_de:"Gezeitenkraft",sum_de:"Die unterschiedlich starke Anziehung eines Körpers an den ihm nahen und fernen Seiten.",exp_de:"Die Schwerkraft eines großen Körpers wirkt auf die nahe Seite stärker als auf die ferne. Das zieht einen anderen Körper in die Länge, wie die Gezeiten der Ozeane auf der Erde. Aus diesem Effekt erwachsen Ebbe und Flut.",name_en:"Tidal Force",sum_en:"The uneven pull of a body on the near and far sides of another.",exp_en:"The gravity of a large body is stronger on the near side of another than on its far side. This stretches the second body, as with the ocean tides on Earth. This effect produces ebb and flood.",name_es:"Fuerza de Marea",sum_es:"La atracción desigual de un cuerpo sobre los lados cercano y lejano de otro.",exp_es:"La gravedad de un cuerpo grande es más intensa en el lado cercano de otro que en el lejano. Esto estira al segundo cuerpo, como ocurre con las mareas oceánicas en la Tierra. De este efecto nacen la pleamar y la bajamar.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="20" fill="#fff"/><circle cx="40" cy="50" r="6" fill="#fff"/><path d="M100 50h-56M100 50l-56-6M100 50l-56 6" stroke="#fff" stroke-width="1" opacity=".6"/></svg>`,related:["moon","gravity","earth"]},
  {id:"tidal-locking",icon:"moon",name_de:"Gebundene Rotation",sum_de:"Wenn ein Körper dem anderen immer dieselbe Seite zuwendet.",exp_de:"Der Mond dreht sich in derselben Zeit um sich selbst, in der er die Erde umrundet. Deshalb sehen wir von der Erde aus immer nur eine Seite. Solche gebundenen Rotationen entstehen durch Gezeitenkräfte und sind bei vielen Monden verbreitet.",name_en:"Tidal Locking",sum_en:"When one body always shows the same face to another.",exp_en:"The Moon spins on its axis in the same time it takes to orbit the Earth. That is why we always see only one side from Earth. Such locked rotations arise from tidal forces and are common among many moons.",name_es:"Acoplamiento de Marea",sum_es:"Cuando un cuerpo muestra siempre la misma cara a otro.",exp_es:"La Luna gira sobre su eje en el mismo tiempo que tarda en orbitar la Tierra. Por eso desde la Tierra vemos siempre una sola cara. Estas rotaciones acopladas surgen de las fuerzas de marea y son comunes en muchas lunas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="70" cy="50" r="22" fill="#fff"/><circle cx="70" cy="50" r="4" fill="#000"/><ellipse cx="140" cy="50" rx="30" ry="30" fill="none" stroke="#fff" stroke-dasharray="3 4" opacity=".6"/><circle cx="140" cy="50" r="10" fill="#fff"/><circle cx="140" cy="50" r="2.5" fill="#000"/></svg>`,related:["moon","tidal-force","earth"]},
  {id:"solar-flare",icon:"sun",name_de:"Sonnenflare",sum_de:"Ein plötzlicher Ausbruch von Strahlung auf der Sonnenoberfläche.",exp_de:"In starken Magnetfeldern der Sonne kann sich Energie schlagartig entladen. Ein Flare sendet Röntgen- und UV-Strahlung aus und kann den Funkverkehr auf der Erde stören. Oft folgt ihm ein koronaler Massenauswurf.",name_en:"Solar Flare",sum_en:"A sudden burst of radiation from the Sun's surface.",exp_en:"Energy can discharge all at once in the Sun's strong magnetic fields. A flare emits X-ray and UV radiation and can disrupt radio communication on Earth. A coronal mass ejection often follows.",name_es:"Llamarada Solar",sum_es:"Una súbita emisión de radiación desde la superficie del Sol.",exp_es:"En los intensos campos magnéticos del Sol la energía puede liberarse de golpe. Una llamarada emite rayos X y ultravioleta y puede alterar las comunicaciones de radio en la Tierra. A menudo la sigue una eyección de masa coronal.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="70" r="34" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M100 30V8M74 40L56 22M126 40l18-18" stroke="#fff" stroke-width="2"/><path d="M100 8l-6-6M100 8l6-6" stroke="#fff" stroke-width="1.5"/></svg>`,related:["sun","coronal-mass-ejection","aurora"]},
  {id:"coronal-mass-ejection",icon:"sun",name_de:"Koronarer Massenauswurf",sum_de:"Eine riesige Wolke aus Sonnenplasma, die ins All geschleudert wird.",exp_de:"Bei einem koronalen Massenauswurf stößt die Sonne Milliarden Tonnen Plasma aus. Trifft die Wolke auf das Erdmagnetfeld, kann sie Polarlichter auslösen und Satelliten stören. Die Teilchen brauchen dafür ein bis drei Tage.",name_en:"Coronal Mass Ejection",sum_en:"A huge cloud of solar plasma hurled into space.",exp_en:"In a coronal mass ejection the Sun throws billions of tonnes of plasma outward. If the cloud meets the Earth's magnetic field, it can trigger auroras and disturb satellites. The particles need one to three days to arrive.",name_es:"Eyección de Masa Coronal",sum_es:"Una enorme nube de plasma solar lanzada al espacio.",exp_es:"En una eyección de masa coronal el Sol expulsa miles de millones de toneladas de plasma. Si la nube alcanza el campo magnético terrestre, puede provocar auroras y alterar satélites. Las partículas tardan de uno a tres días en llegar.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="40" cy="50" r="18" fill="#fff"/><path d="M60 34q40-10 80 8M60 50q45 0 88 0M60 66q40 12 80-6" fill="none" stroke="#fff" stroke-width="1.2" opacity=".7"/><circle cx="150" cy="46" r="8" fill="none" stroke="#fff" stroke-dasharray="3 3"/><circle cx="170" cy="56" r="6" fill="none" stroke="#fff" stroke-dasharray="3 3" opacity=".6"/></svg>`,related:["sun","solar-wind","aurora"]},
  {id:"sunspot",icon:"sun",name_de:"Sonnenfleck",sum_de:"Eine kühlere, dunklere Stelle auf der Sonnenoberfläche, wo Magnetfelder stark sind.",exp_de:"Sonnenflecken entstehen, wo starke Magnetfelder den Wärmetransport in der Sonne stören. Sie erscheinen deshalb dunkler und kühler als ihre Umgebung. Ihre Zahl schwankt im elfjährigen Sonnenzyklus.",name_en:"Sunspot",sum_en:"A cooler, darker patch on the Sun's surface where magnetic fields are strong.",exp_en:"Sunspots form where strong magnetic fields hinder the transport of heat in the Sun. They therefore appear darker and cooler than their surroundings. Their number varies over the eleven-year solar cycle.",name_es:"Mancha Solar",sum_es:"Una zona más fría y oscura en la superficie del Sol donde el campo magnético es intenso.",exp_es:"Las manchas solares surgen donde fuertes campos magnéticos dificultan el transporte de calor en el Sol. Por eso parecen más oscuras y frías que su entorno. Su número varía según el ciclo solar de once años.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="36" fill="none" stroke="#fff" stroke-width="1.5"/><circle cx="86" cy="42" r="7" fill="#fff"/><circle cx="118" cy="58" r="5" fill="#fff"/><circle cx="104" cy="34" r="3.5" fill="#fff"/><path d="M70 40q20-10 34 4" fill="none" stroke="#fff" opacity=".5"/></svg>`,related:["sun","solar-cycle","solar-flare"]},
  {id:"solar-cycle",icon:"sun",name_de:"Sonnenzyklus",sum_de:"Der etwa elfjährige Wechsel der Sonnenaktivität.",exp_de:"Die magnetische Aktivität der Sonne schwankt in einem Zyklus von rund elf Jahren. Zu Höhepunkten gibt es viele Sonnenflecken, Flares und Auswürfe. Danach folgt eine ruhigere Phase.",name_en:"Solar Cycle",sum_en:"The roughly eleven-year variation in solar activity.",exp_en:"The Sun's magnetic activity varies in a cycle of about eleven years. At its peaks there are many sunspots, flares and ejections. A quieter phase follows.",name_es:"Ciclo Solar",sum_es:"La variación de la actividad solar de unos once años.",exp_es:"La actividad magnética del Sol varía en un ciclo de unos once años. En los máximos hay muchas manchas, llamaradas y eyecciones. Después sigue una fase más tranquila.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M20 70q30-56 60 0t60 0 40-20" fill="none" stroke="#fff" stroke-width="1.6"/><path d="M20 84h160" stroke="#fff" opacity=".5"/><path d="M100 46V20M100 20l-5 6M100 20l5 6" stroke="#fff" stroke-width="1.2"/></svg>`,related:["sun","sunspot","solar-flare"]},
  {id:"heliosphere",icon:"sun",name_de:"Heliosphäre",sum_de:"Die riesige Blase aus Sonnenwind um das Sonnensystem.",exp_de:"Der Sonnenwind bläst eine Blase in das interstellare Medium, die Heliosphäre. Ihre Grenze, die Heliopause, erreichten die Voyager-Sonden. Sie schützt das Sonnensystem teilweise vor kosmischer Strahlung.",name_en:"Heliosphere",sum_en:"The vast bubble of solar wind around the Solar System.",exp_en:"The solar wind blows a bubble into the interstellar medium, the heliosphere. The Voyager probes reached its boundary, the heliopause. It partly shields the Solar System from cosmic rays.",name_es:"Heliosfera",sum_es:"La enorme burbuja de viento solar que rodea el sistema solar.",exp_es:"El viento solar sopla una burbuja en el medio interestelar: la heliosfera. Las sondas Voyager alcanzaron su límite, la heliopausa. Protege en parte al sistema solar de los rayos cósmicos.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="60" cy="50" r="8" fill="#fff"/><ellipse cx="90" cy="50" rx="52" ry="34" fill="none" stroke="#fff" stroke-width="1.4"/><path d="M140 34c14 8 22 10 34 10M140 66c14-8 22-10 34-10" fill="none" stroke="#fff" stroke-dasharray="3 4" opacity=".7"/></svg>`,related:["sun","solar-wind","cosmic-ray"]},
  {id:"telescope",icon:"telescope",name_de:"Teleskop",sum_de:"Ein Gerät, das Licht sammelt und ferne Objekte vergrößert zeigt.",exp_de:"Teleskope bündeln mit Linsen oder Spiegeln das Licht ferner Objekte. Je größer die Öffnung, desto schwächer die noch sichtbaren Objekte und desto schärfer das Bild. Sie sind das wichtigste Werkzeug der Astronomie.",name_en:"Telescope",sum_en:"A device that gathers light and magnifies distant objects.",exp_en:"Telescopes collect the light of distant objects with lenses or mirrors. The larger the aperture, the fainter the objects visible and the sharper the image. They are astronomy's most important tool.",name_es:"Telescopio",sum_es:"Un instrumento que recoge luz y amplía los objetos lejanos.",exp_es:"Los telescopios concentran con lentes o espejos la luz de objetos lejanos. Cuanto mayor es la apertura, más débiles son los objetos visibles y más nítida la imagen. Son la herramienta más importante de la astronomía.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M60 34l84 24-6 12-84-24z" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M60 22v24M60 22l-14 10 14 10" fill="none" stroke="#fff"/><path d="M100 60l-8 26h30l-8-26" fill="none" stroke="#fff"/><path d="M74 84h52" stroke="#fff" stroke-width="2"/></svg>`,related:["observatory","hubble","jwst"]},
  {id:"observatory",icon:"telescope",name_de:"Observatorium",sum_de:"Ein Ort mit Instrumenten zur Beobachtung des Himmels.",exp_de:"Observatorien liegen oft hoch auf Bergen oder in trockenen Wüsten, wo die Luft klar und dunkel ist. Dort stehen Teleskope dauerhaft, geschützt in Kuppeln. Manche Observatorien beobachten auch Radiowellen oder Neutrinos.",name_en:"Observatory",sum_en:"A site with instruments for observing the sky.",exp_en:"Observatories are often high on mountains or in dry deserts, where the air is clear and dark. Telescopes stand there permanently, sheltered in domes. Some observatories also observe radio waves or neutrinos.",name_es:"Observatorio",sum_es:"Un lugar con instrumentos para observar el cielo.",exp_es:"Los observatorios suelen estar en montañas altas o desiertos secos, donde el aire es limpio y oscuro. Allí los telescopios permanecen, resguardados en cúpulas. Algunos observatorios también captan ondas de radio o neutrinos.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M52 76a48 48 0 0 1 96 0z" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M100 28v-8M100 20h-16" stroke="#fff"/><path d="M40 76h120" stroke="#fff" stroke-width="1.5"/><path d="M78 76l-8-6M122 76l8-6" stroke="#fff" opacity=".6"/></svg>`,related:["telescope","radio-telescope","hubble"]},
  {id:"hubble",icon:"telescope",name_de:"Hubble-Weltraumteleskop",sum_de:"Ein berühmtes Weltraumteleskop, das seit 1990 die Tiefen des Alls beobachtet.",exp_de:"Hubble kreist oberhalb der störenden Erdatmosphäre und liefert seit 1990 gestochen scharfe Bilder. Es hat die Expansion des Universums und die Entstehung von Galaxien erforscht. Seine deep-field-Aufnahmen zeigen viele tausend Galaxien in einem winzigen Himmelsfeld.",name_en:"Hubble Space Telescope",sum_en:"A famous space telescope observing the depths of space since 1990.",exp_en:"Hubble orbits above the disturbing atmosphere and has delivered razor-sharp images since 1990. It has studied the expansion of the universe and the birth of galaxies. Its deep-field images show many thousands of galaxies in a tiny patch of sky.",name_es:"Telescopio Espacial Hubble",sum_es:"Un famoso telescopio espacial que observa el cosmos desde 1990.",exp_es:"Hubble orbita por encima de la atmósfera y desde 1990 ofrece imágenes nítidas. Ha estudiado la expansión del universo y el nacimiento de galaxias. Sus imágenes de campo profundo muestran miles de galaxias en una diminuta zona del cielo.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><rect x="60" y="42" width="70" height="18" rx="3" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M45 50h15M130 50h18" stroke="#fff" stroke-width="2"/><path d="M95 42v-10h20v10" fill="none" stroke="#fff"/><path d="M60 74h100" stroke="#fff" stroke-dasharray="4 4" opacity=".5"/></svg>`,related:["telescope","jwst","observatory"]},
  {id:"jwst",icon:"telescope",name_de:"James-Webb-Weltraumteleskop",sum_de:"Das große Infrarot-Weltraumteleskop, das seit 2022 das frühe Universum erkundet.",exp_de:"Das James-Webb-Teleskop beobachtet im Infraroten und blickt damit weiter in die Vergangenheit als Hubble. Sein großer Spiegel sammelt das Licht der ersten Galaxien. Es untersucht auch Atmosphären von Exoplaneten.",name_en:"James Webb Space Telescope",sum_en:"The large infrared space telescope exploring the early universe since 2022.",exp_en:"The James Webb telescope observes in the infrared and so looks further back in time than Hubble. Its large mirror gathers the light of the first galaxies. It also studies the atmospheres of exoplanets.",name_es:"Telescopio Espacial James Webb",sum_es:"El gran telescopio infrarrojo espacial que explora el universo temprano desde 2022.",exp_es:"El telescopio James Webb observa en infrarrojo y por ello mira más atrás en el tiempo que Hubble. Su gran espejo recoge la luz de las primeras galaxias. También estudia atmósferas de exoplanetas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="46" r="26" fill="none" stroke="#fff" stroke-width="1.2"/><path d="M74 46h52M100 20v52M82 28l36 36M118 28l-36 36" stroke="#fff" opacity=".6"/><path d="M70 78h60l-10-12h-40z" fill="none" stroke="#fff" stroke-width="1.5"/></svg>`,related:["telescope","hubble","exoplanet"]},
  {id:"radio-telescope",icon:"telescope",name_de:"Radioteleskop",sum_de:"Ein Instrument, das Radiowellen aus dem All empfängt.",exp_de:"Radioteleskope sind große Schüsseln, die Radiowellen ferner Objekte bündeln. Sie können auch durch Wolken und Staub beobachten, wo sichtbares Licht nicht durchkommt. Pulsare, kalte Gaswolken und ferne Radiogalaxien sind ihre Spezialgebiete.",name_en:"Radio Telescope",sum_en:"An instrument that receives radio waves from space.",exp_en:"Radio telescopes are large dishes that collect radio waves from distant objects. They can also observe through clouds and dust where visible light cannot pass. Pulsars, cold gas clouds and distant radio galaxies are their specialities.",name_es:"Radiotelescopio",sum_es:"Un instrumento que recibe ondas de radio del espacio.",exp_es:"Los radiotelescopios son grandes antenas que concentran ondas de radio de objetos lejanos. También pueden observar a través de nubes y polvo, donde la luz visible no pasa. Púlsares, nubes frías de gas y radiogalaxias lejanas son su especialidad.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M60 60a40 40 0 0 0 80 0" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M60 60h80" stroke="#fff" stroke-width="1.5"/><path d="M100 60l-24 24M100 60l24 24" stroke="#fff"/><path d="M100 30v-14M86 22l14-6 14 6" stroke="#fff" opacity=".7"/></svg>`,related:["telescope","pulsar","observatory"]},
  {id:"spectroscopy",icon:"lightyear",name_de:"Spektroskopie",sum_de:"Das Zerlegen von Licht in seine Farben, um die Zusammensetzung zu erforschen.",exp_de:"Ein Spektroskop breitet das Licht eines Objekts in seine Wellenlängen aus. Dunkle oder helle Linien verraten, aus welchen Elementen es besteht und wie schnell es sich bewegt. So kennt man die Chemie ferner Sterne, ohne sie zu berühren.",name_en:"Spectroscopy",sum_en:"Splitting light into its colours to study composition.",exp_en:"A spectroscope spreads the light of an object into its wavelengths. Dark or bright lines reveal which elements it contains and how fast it moves. This is how we know the chemistry of distant stars without touching them.",name_es:"Espectroscopía",sum_es:"Separar la luz en sus colores para estudiar la composición.",exp_es:"Un espectroscopio despliega la luz de un objeto en sus longitudes de onda. Las líneas oscuras o brillantes revelan qué elementos contiene y a qué velocidad se mueve. Así conocemos la química de estrellas lejanas sin tocarlas.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M50 50l100-22v44z" fill="none" stroke="#fff" stroke-width="1.2"/><path d="M50 50h36" stroke="#fff" stroke-width="1.5"/><path d="M150 28v44" stroke="#fff"/><path d="M156 36h34M156 50h30M156 64h36" stroke="#fff" stroke-width="2"/></svg>`,related:["electromagnetic-spectrum","doppler-effect","hubble"]},
  {id:"magnitude",icon:"star",name_de:"Scheinbare Helligkeit",sum_de:"Ein Maß dafür, wie hell ein Himmelskörper uns erscheint.",exp_de:"Die scheinbare Helligkeit gibt an, wie hell ein Objekt am Himmel leuchtet. Je kleiner der Wert, desto heller; die Sonne hat etwa minus 27, der Polarstern rund 2. Sie hängt sowohl von der echten Leuchtkraft als auch von der Entfernung ab.",name_en:"Apparent Magnitude",sum_en:"A measure of how bright a celestial body appears to us.",exp_en:"Apparent magnitude states how bright an object shines in the sky. The smaller the value, the brighter; the Sun is about minus 27, the North Star about 2. It depends both on true luminosity and on distance.",name_es:"Magnitud Aparente",sum_es:"Una medida de cuán brillante nos parece un astro.",exp_es:"La magnitud aparente indica cuán brillante luce un objeto en el cielo. Cuanto menor es el valor, más brillante; el Sol es de unos menos 27 y la Estrella Polar de unos 2. Depende tanto de la luminosidad real como de la distancia.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="50" cy="50" r="10" fill="#fff"/><circle cx="110" cy="50" r="6" fill="#fff" opacity=".8"/><circle cx="160" cy="50" r="3.5" fill="#fff" opacity=".6"/><path d="M50 50l-14-8M50 50l-20 0M50 50l-14 8" stroke="#fff" stroke-width="1" opacity=".7"/></svg>`,related:["star","lightyear","spectroscopy"]},
  {id:"ecliptic",icon:"orbit",name_de:"Ekliptik",sum_de:"Die scheinbare jährliche Bahn der Sonne am Himmel.",exp_de:"Die Ekliptik ist die Ebene, in der die Erde die Sonne umrundet, projiziert auf den Himmel. Sonne und Planeten bewegen sich nahe dieser Linie. Die zwölf Tierkreiszeichen liegen entlang der Ekliptik.",name_en:"Ecliptic",sum_en:"The apparent yearly path of the Sun across the sky.",exp_en:"The ecliptic is the plane in which the Earth orbits the Sun, projected onto the sky. The Sun and planets move near this line. The twelve zodiac signs lie along the ecliptic.",name_es:"Eclíptica",sum_es:"La trayectoria anual aparente del Sol en el cielo.",exp_es:"La eclíptica es el plano en que la Tierra orbita al Sol, proyectado en el cielo. El Sol y los planetas se mueven cerca de esta línea. Los doce signos del zodiaco se sitúan a lo largo de la eclíptica.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="34" fill="none" stroke="#fff" stroke-dasharray="4 4" opacity=".5"/><ellipse cx="100" cy="50" rx="72" ry="20" fill="none" stroke="#fff" stroke-width="1.4"/><circle cx="100" cy="50" r="8" fill="#fff"/><circle cx="30" cy="50" r="3" fill="#fff"/></svg>`,related:["orbit","earth","perihel"]},
  {id:"astronaut",icon:"astronaut",name_de:"Astronaut",sum_de:"Eine Person, die im Weltraum arbeitet und forscht.",exp_de:"Astronautinnen und Astronauten trainieren jahrelang für den Flug ins All. An Bord einer Raumstation leben und arbeiten sie in Schwerelosigkeit. Bei Außenbordeinsätzen sichern sie Raumanzug und Sicherungsleine.",name_en:"Astronaut",sum_en:"A person who works and does research in space.",exp_en:"Astronauts train for years for their flight into space. Aboard a space station they live and work in weightlessness. During spacewalks a spacesuit and tether keep them safe.",name_es:"Astronauta",sum_es:"Una persona que trabaja e investiga en el espacio.",exp_es:"Los astronautas se entrenan durante años para su viaje al espacio. A bordo de una estación espacial viven y trabajan en ingravidez. En los paseos espaciales los protegen el traje y un cable de seguridad.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="34" r="14" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M92 32a8 8 0 0 1 16 0" fill="none" stroke="#fff" opacity=".7"/><path d="M100 48v22M84 56l16 6 16-6M88 70l-8 16M112 70l8 16" fill="none" stroke="#fff" stroke-width="1.5"/></svg>`,related:["spacesuit","spacewalk","iss"]},
  {id:"spacesuit",icon:"astronaut",name_de:"Raumanzug",sum_de:"Ein Schutzanzug, der Menschen im Weltraum lebensfähig macht.",exp_de:"Ein Raumanzug liefert Atemluft, Wärme und Druck, ähnlich wie eine kleine Raumkapsel am Körper. Er schirmt vor Kälte, Strahlung und Mikrometeoriten ab. Im Inneren hält er den Druck aufrecht, damit Körperflüssigkeiten nicht sieden.",name_en:"Spacesuit",sum_en:"A protective suit that keeps humans alive in space.",exp_en:"A spacesuit supplies air, warmth and pressure, much like a small spacecraft worn on the body. It shields against cold, radiation and micrometeorites. Inside it maintains pressure so body fluids do not boil.",name_es:"Traje Espacial",sum_es:"Un traje protector que mantiene vivos a los humanos en el espacio.",exp_es:"Un traje espacial aporta aire, calor y presión, como una pequeña nave puesta en el cuerpo. Protege del frío, la radiación y los micrometeoritos. En su interior mantiene la presión para que los fluidos no hiervan.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="30" r="14" fill="none" stroke="#fff" stroke-width="1.5"/><ellipse cx="100" cy="28" rx="10" ry="8" fill="none" stroke="#fff" opacity=".6"/><path d="M100 44v30M82 54h36M88 74l-10 16M112 74l10 16" fill="none" stroke="#fff" stroke-width="1.5"/></svg>`,related:["astronaut","spacewalk","iss"]},
  {id:"spacewalk",icon:"astronaut",name_de:"Außenbordeinsatz",sum_de:"Die Arbeit eines Astronauten außerhalb eines Raumfahrzeugs.",exp_de:"Bei einem Außenbordeinsatz, oft EVA genannt, verlässt ein Astronaut die Raumstation im Raumanzug. Er montiert, repariert oder experimentiert im freien Weltall. Eine Sicherungsleine verhindert, dass er davon treibt.",name_en:"Spacewalk",sum_en:"An astronaut's work outside a spacecraft.",exp_en:"During a spacewalk, often called EVA, an astronaut leaves the space station in a spacesuit. They assemble, repair or experiment in open space. A tether prevents them from drifting away.",name_es:"Paseo Espacial",sum_es:"El trabajo de un astronauta fuera de una nave espacial.",exp_es:"En un paseo espacial, a menudo llamado EVA, un astronauta sale de la estación con su traje. Monta, repara o experimenta en el espacio abierto. Un cable de seguridad evita que se aleje flotando.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><rect x="60" y="30" width="80" height="40" rx="4" fill="none" stroke="#fff" stroke-width="1.5"/><circle cx="150" cy="50" r="8" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M140 50h-10M150 58l6 12" stroke="#fff" stroke-width="1.5"/><path d="M150 50l24 12" stroke="#fff" stroke-dasharray="3 3" opacity=".5"/></svg>`,related:["astronaut","spacesuit","iss"]},
  {id:"weightlessness",icon:"astronaut",name_de:"Schwerelosigkeit",sum_de:"Der Zustand, in dem man frei zu schweben scheint.",exp_de:"In einer Raumstation ist die Schwerkraft nicht verschwunden, sondern alles fällt gemeinsam um die Erde. Weil sie dieselbe Bahn teilen, schweben die Insassen. Diesen Zustand nennt man Schwerelosigkeit oder Mikrogravitation.",name_en:"Weightlessness",sum_en:"The state of seeming to float freely.",exp_en:"Aboard a space station gravity has not vanished; everything falls around the Earth together. Because they share the same orbit, the occupants float. This state is called weightlessness or microgravity.",name_es:"Ingravidez",sum_es:"El estado en que uno parece flotar libremente.",exp_es:"En una estación espacial la gravedad no ha desaparecido: todo cae alrededor de la Tierra a la vez. Como comparten la misma órbita, sus ocupantes flotan. Este estado se llama ingravidez o microgravedad.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="34" fill="none" stroke="#fff" stroke-width="1.4" opacity=".6"/><circle cx="100" cy="30" r="7" fill="#fff"/><path d="M100 37v16M92 44l8 5 8-5M96 53l-4 14M104 53l4 14" fill="none" stroke="#fff" stroke-width="1.3"/></svg>`,related:["iss","astronaut","orbit"]},
  {id:"reentry",icon:"rocket",name_de:"Wiedereintritt",sum_de:"Das Eintreten eines Raumfahrzeugs in die Erdatmosphäre.",exp_de:"Beim Wiedereintritt taucht ein Raumschiff mit enormer Geschwindigkeit in die Atmosphäre ein. Die Reibung erzeugt ein glühend heißes Plasma und bremst die Kapsel ab. Ein Hitzeschild schützt die Insassen vor dieser Hitze.",name_en:"Atmospheric Reentry",sum_en:"A spacecraft's entry into the Earth's atmosphere.",exp_en:"During reentry a spacecraft plunges into the atmosphere at enormous speed. Friction creates a glowing hot plasma and slows the capsule. A heat shield protects the occupants from the heat.",name_es:"Reentrada",sum_es:"La entrada de una nave en la atmósfera terrestre.",exp_es:"En la reentrada una nave penetra en la atmósfera a enorme velocidad. La fricción genera un plasma incandescente y frena la cápsula. Un escudo térmico protege a los ocupantes de ese calor.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M60 14l24 44-24 12-24-12z" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M36 58q14 22 48 22t48-22" fill="none" stroke="#fff" opacity=".6"/><path d="M48 70l-8 8M60 76l-4 10M72 70l8 8" stroke="#fff" stroke-width="1.2"/><path d="M150 20v60" stroke="#fff" stroke-dasharray="4 4" opacity=".4"/></svg>`,related:["escape-velocity","rakete","atmosphere"]},
  {id:"escape-velocity",icon:"rocket",name_de:"Fluchtgeschwindigkeit",sum_de:"Die Mindestgeschwindigkeit, um die Schwerkraft eines Himmelskörpers zu überwinden.",exp_de:"Um die Erde endgültig zu verlassen, muss eine Sonde rund 11,2 Kilometer pro Sekunde erreichen. Wer langsamer ist, fällt wieder zurück oder bleibt in einer Umlaufbahn. Je massereicher und größer ein Körper, desto höher diese Geschwindigkeit.",name_en:"Escape Velocity",sum_en:"The minimum speed needed to overcome a body's gravity.",exp_en:"To leave the Earth for good, a probe must reach about 11.2 kilometres per second. Anything slower falls back or stays in orbit. The more massive and larger a body, the higher this speed.",name_es:"Velocidad de Escape",sum_es:"La velocidad mínima para vencer la gravedad de un astro.",exp_es:"Para abandonar la Tierra definitivamente, una sonda debe alcanzar unos 11,2 kilómetros por segundo. Lo más lento vuelve a caer o queda en órbita. Cuanto más masivo y grande es un cuerpo, mayor es esa velocidad.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="80" r="26" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M100 54V12M100 12l-6 8M100 12l6 8" stroke="#fff" stroke-width="1.8"/><path d="M50 80h100" stroke="#fff" stroke-dasharray="4 4" opacity=".5"/></svg>`,related:["rakete","gravity","earth"]},
  {id:"space-debris",icon:"satellite",name_de:"Weltraumschrott",sum_de:"Alte Satelliten und Trümmerteile, die die Erde umkreisen.",exp_de:"Seit Beginn der Raumfahrt sammeln sich ausgediente Satelliten, Raketenteile und Splitter im Orbit. Sie rasen mit vielfacher Gewehrkugel-Geschwindigkeit und gefährden aktive Raumfahrzeuge. Kollisionen können immer mehr Trümmer erzeugen.",name_en:"Space Debris",sum_en:"Old satellites and fragments orbiting the Earth.",exp_en:"Since the dawn of spaceflight, spent satellites, rocket parts and shards have accumulated in orbit. They race at many times the speed of a rifle bullet and endanger active spacecraft. Collisions can produce ever more debris.",name_es:"Basura Espacial",sum_es:"Satélites viejos y fragmentos que orbitan la Tierra.",exp_es:"Desde el inicio de la era espacial se acumulan en órbita satélites obsoletos, restos de cohetes y fragmentos. Vuelan a muchas veces la velocidad de una bala y ponen en peligro a las naves activas. Las colisiones pueden generar aún más basura.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="34" fill="none" stroke="#fff" stroke-width="1.4" opacity=".6"/><rect x="60" y="40" width="16" height="10" fill="none" stroke="#fff"/><path d="M120 30l6 6M130 42h8M112 62l-6 6M138 30l-5 4M90 26h10M84 68h12" stroke="#fff" stroke-width="2"/></svg>`,related:["satellite","iss","orbit"]},
  {id:"satellite",icon:"satellite",name_de:"Satellit",sum_de:"Ein künstlicher Körper, der einen Himmelskörper umkreist.",exp_de:"Satelliten umkreisen die Erde für Wetter, Kommunikation, Navigation und Forschung. Sie bleiben in ihrer Bahn, weil ihre Vorwärtsbewegung und die Schwerkraft zusammenspielen. Manche stehen über demselben Punkt der Erde still.",name_en:"Satellite",sum_en:"An artificial body orbiting a celestial body.",exp_en:"Satellites orbit the Earth for weather, communication, navigation and research. They stay in their path because their forward motion and gravity work together. Some remain still above the same point on Earth.",name_es:"Satélite",sum_es:"Un cuerpo artificial que orbita un astro.",exp_es:"Los satélites orbitan la Tierra para el clima, las comunicaciones, la navegación y la investigación. Se mantienen en su órbita porque su movimiento y la gravedad actúan juntos. Algunos permanecen fijos sobre el mismo punto de la Tierra.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="100" cy="50" r="20" fill="none" stroke="#fff" stroke-width="1.5"/><rect x="66" y="44" width="14" height="12" fill="none" stroke="#fff"/><path d="M66 46h-12M66 54h-12" stroke="#fff"/><path d="M60 40l-6-6M60 60l-6 6" stroke="#fff" stroke-width="1.5"/><ellipse cx="100" cy="50" rx="70" ry="26" fill="none" stroke="#fff" stroke-dasharray="4 4" opacity=".5"/></svg>`,related:["orbit","iss","space-debris"]},
  {id:"lagrange-point",icon:"orbit",name_de:"Lagrange-Punkt",sum_de:"Ein Gleichgewichtsort im System zweier großer Himmelskörper.",exp_de:"Zwischen Erde und Sonne gibt es fünf Punkte, an denen sich die Kräfte gerade ausgleichen. Ein Körper dort kann dem kleineren Partner mit derselben Bahn folgen. Das James-Webb-Teleskop nutzt den zweiten Lagrange-Punkt.",name_en:"Lagrange Point",sum_en:"A balance point in the system of two large bodies.",exp_en:"Between the Earth and the Sun there are five points where the forces just balance. A body there can follow the smaller partner on the same orbit. The James Webb telescope uses the second Lagrange point.",name_es:"Punto de Lagrange",sum_es:"Un punto de equilibrio en el sistema de dos grandes cuerpos.",exp_es:"Entre la Tierra y el Sol hay cinco puntos donde las fuerzas se equilibran. Un cuerpo allí puede seguir al socio menor en la misma órbita. El telescopio James Webb usa el segundo punto de Lagrange.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="40" cy="50" r="14" fill="#fff"/><circle cx="160" cy="50" r="7" fill="#fff"/><path d="M54 50h99" stroke="#fff" stroke-dasharray="3 4" opacity=".5"/><circle cx="74" cy="50" r="3" fill="none" stroke="#fff"/><circle cx="110" cy="50" r="3" fill="none" stroke="#fff"/><circle cx="178" cy="50" r="3" fill="none" stroke="#fff"/></svg>`,related:["jwst","orbit","earth"]},
  {id:"ion-drive",icon:"rocket",name_de:"Ionenantrieb",sum_de:"Ein sehr sparsamer Antrieb, der Ionen beschleunigt ausstößt.",exp_de:"Ein Ionenantrieb beschleunigt geladene Teilchen mit elektrischer Energie und stößt sie mit hoher Geschwindigkeit aus. Der Schub ist klein, aber er hält monatelang an. So erreichen Sonden hohe Endgeschwindigkeiten mit wenig Treibstoff.",name_en:"Ion Drive",sum_en:"A very frugal engine that expels accelerated ions.",exp_en:"An ion drive accelerates charged particles with electrical energy and expels them at high speed. The thrust is small, but it lasts for months. In this way probes reach high final speeds with little fuel.",name_es:"Motor Iónico",sum_es:"Un motor muy económico que expulsa iones acelerados.",exp_es:"Un motor iónico acelera partículas cargadas con energía eléctrica y las expulsa a gran velocidad. El empuje es pequeño, pero dura meses. Así las sondas alcanzan altas velocidades finales con poco combustible.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M60 40h44l20 10-20 10H60z" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M60 46v8" stroke="#fff"/><path d="M124 50h56" stroke="#fff" stroke-dasharray="2 5" opacity=".7"/><circle cx="140" cy="46" r="2" fill="#fff"/><circle cx="150" cy="54" r="2" fill="#fff"/><circle cx="160" cy="48" r="2" fill="#fff"/></svg>`,related:["rakete","voyager","sonde"]},
  {id:"apollo",icon:"rocket",name_de:"Apollo-Programm",sum_de:"Das Programm, das erstmals Menschen auf den Mond brachte.",exp_de:"Zwischen 1969 und 1972 landeten sechs Apollo-Missionen auf dem Mond. Neil Armstrong und Buzz Aldrin betraten am 20. Juli 1969 als Erste die Oberfläche. Das Programm sammelte hunderte Kilogramm Gestein und beendete das Wettrennen zum Mond.",name_en:"Apollo Program",sum_en:"The program that first brought humans to the Moon.",exp_en:"Between 1969 and 1972 six Apollo missions landed on the Moon. Neil Armstrong and Buzz Aldrin first stepped onto the surface on 20 July 1969. The program collected hundreds of kilograms of rock and ended the race to the Moon.",name_es:"Programa Apolo",sum_es:"El programa que llevó por primera vez a humanos a la Luna.",exp_es:"Entre 1969 y 1972 seis misiones Apolo aterrizaron en la Luna. Neil Armstrong y Buzz Aldrin pisaron la superficie por primera vez el 20 de julio de 1969. El programa recogió cientos de kilos de roca y puso fin a la carrera a la Luna.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M100 13c16 14 16 48 0 62-16-14-16-48 0-62z" fill="none" stroke="#fff" stroke-width="1.5"/><circle cx="100" cy="40" r="6" fill="none" stroke="#fff"/><path d="M86 62l-14 20M114 62l14 20" stroke="#fff" stroke-width="1.3"/><path d="M96 75q4 14 8 0" fill="none" stroke="#fff" opacity=".7"/></svg>`,related:["moon","rakete","astronaut"]},
  {id:"artemis",icon:"rocket",name_de:"Artemis-Programm",sum_de:"Das neue Programm, das Menschen wieder zum Mond bringen soll.",exp_de:"Das Artemis-Programm der NASA will Menschen zurück auf den Mond bringen und dort dauerhaft forschen. Geplant sind auch die erste Frau und der erste farbige Astronaut auf der Oberfläche. Langfristig soll der Mond als Zwischenstation zum Mars dienen.",name_en:"Artemis Program",sum_en:"The new program aiming to return humans to the Moon.",exp_en:"NASA's Artemis program aims to bring humans back to the Moon and to research there for the long term. The first woman and the first person of colour on the surface are also planned. In the long run the Moon is to serve as a stepping stone to Mars.",name_es:"Programa Artemis",sum_es:"El nuevo programa para llevar de nuevo a humanos a la Luna.",exp_es:"El programa Artemis de la NASA quiere llevar de nuevo a humanos a la Luna y hacer investigación duradera. También se planean la primera mujer y la primera persona racializada en la superficie. A largo plazo la Luna servirá de escala hacia Marte.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><path d="M70 30a26 26 0 1 0 30 40" fill="none" stroke="#fff" stroke-width="1.6"/><circle cx="70" cy="50" r="10" fill="none" stroke="#fff" opacity=".5"/><path d="M124 20c12 10 12 50 0 60-12-10-12-50 0-60z" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M114 62l-10 16M134 62l10 16" stroke="#fff" stroke-width="1.2"/></svg>`,related:["apollo","moon","rakete"]},
  {id:"voyager",icon:"satellite",name_de:"Voyager-Sonden",sum_de:"Zwei Sonden, die zu den entferntesten Boten der Menschheit wurden.",exp_de:"Die Sonden Voyager 1 und 2 starteten 1977 zur Erforschung der äußeren Planeten. Sie flogen an Jupiter, Saturn, Uranus und Neptun vorbei und verließen danach das Sonnensystem. Jede trägt eine goldene Platte mit Grüßen und Musik der Erde.",name_en:"Voyager Probes",sum_en:"Two probes that became humanity's most distant messengers.",exp_en:"Voyager 1 and 2 launched in 1977 to explore the outer planets. They flew past Jupiter, Saturn, Uranus and Neptune and then left the Solar System. Each carries a golden record with greetings and music from Earth.",name_es:"Sondas Voyager",sum_es:"Dos sondas que se convirtieron en los mensajeros más lejanos de la humanidad.",exp_es:"Las Voyager 1 y 2 se lanzaron en 1977 para explorar los planetas exteriores. Pasaron junto a Júpiter, Saturno, Urano y Neptuno y luego dejaron el sistema solar. Cada una lleva un disco dorado con saludos y música de la Tierra.",graphic:`<svg width="220" height="120" viewBox="0 0 200 100"><circle cx="60" cy="50" r="10" fill="none" stroke="#fff" stroke-width="1.5"/><path d="M70 50h50" stroke="#fff"/><path d="M120 36v28M140 36v28M120 50h20" stroke="#fff" opacity=".7"/><path d="M160 50h26" stroke="#fff" stroke-dasharray="3 4" opacity=".6"/></svg>`,related:["ion-drive","heliosphere","sonde"]}
];
